INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q1 Item 1 (TPS 2003): QUESTÃO 1 (TPS 2003) — Texto "Mistura linguística": trecho sobre hibridismo de línguas, globalização e identidade cultural na era contemporânea, discutindo o papel do inglês como língua franca e as resistências das línguas nacionais. Com base no texto acima, julgue os itens a seguir. [A ocorrência de empréstimos lexicais do inglês em outras línguas é fenômeno recente, impulsionado pela globalização econômica e cultural do século XX.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q1 Item 2 (TPS 2003): QUESTÃO 1 (TPS 2003) — Texto "Mistura linguística": trecho sobre hibridismo de línguas, globalização e identidade cultural na era contemporânea, discutindo o papel do inglês como língua franca e as resistências das línguas nacionais. Com base no texto acima, julgue os itens a seguir. [A mistura linguística implica necessariamente perda de identidade cultural dos povos que adotam vocábulos estrangeiros em sua comunicação cotidiana.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q1 Item 3 (TPS 2003): QUESTÃO 1 (TPS 2003) — Texto "Mistura linguística": trecho sobre hibridismo de línguas, globalização e identidade cultural na era contemporânea, discutindo o papel do inglês como língua franca e as resistências das línguas nacionais. Com base no texto acima, julgue os itens a seguir. [O texto sugere que a resistência à incorporação de termos estrangeiros pode ser compreendida como afirmação de soberania cultural e identidade nacional.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q1 Item 4 (TPS 2003): QUESTÃO 1 (TPS 2003) — Texto "Mistura linguística": trecho sobre hibridismo de línguas, globalização e identidade cultural na era contemporânea, discutindo o papel do inglês como língua franca e as resistências das línguas nacionais. Com base no texto acima, julgue os itens a seguir. [Segundo o texto, o hibridismo linguístico é tratado pelos autores como fenômeno essencialmente negativo, ameaçando a coesão social das comunidades.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q1 Item 5 (TPS 2003): QUESTÃO 1 (TPS 2003) — Texto "Mistura linguística": trecho sobre hibridismo de línguas, globalização e identidade cultural na era contemporânea, discutindo o papel do inglês como língua franca e as resistências das línguas nacionais. Com base no texto acima, julgue os itens a seguir. [A função predominante do texto é argumentativa, mobilizando exemplos de diferentes línguas para sustentar uma tese sobre o impacto da globalização na linguagem.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q2 Item 1 (TPS 2003): QUESTÃO 2 (TPS 2003) — Texto "Poder" (1ª parte): trecho de análise política e filosófica sobre as dimensões do poder, suas formas de legitimação e a relação entre discurso, autoridade e dominação nas sociedades modernas. Com base no texto acima, julgue os itens a seguir. [O texto estabelece distinção entre poder coercitivo e poder simbólico, indicando que ambos operam simultaneamente nas relações sociais.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q2 Item 2 (TPS 2003): QUESTÃO 2 (TPS 2003) — Texto "Poder" (1ª parte): trecho de análise política e filosófica sobre as dimensões do poder, suas formas de legitimação e a relação entre discurso, autoridade e dominação nas sociedades modernas. Com base no texto acima, julgue os itens a seguir. [De acordo com o texto, a legitimação do poder prescinde do discurso, baseando-se exclusivamente na força física e no controle dos aparatos do Estado.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q2 Item 3 (TPS 2003): QUESTÃO 2 (TPS 2003) — Texto "Poder" (1ª parte): trecho de análise política e filosófica sobre as dimensões do poder, suas formas de legitimação e a relação entre discurso, autoridade e dominação nas sociedades modernas. Com base no texto acima, julgue os itens a seguir. [O autor sustenta que a linguagem desempenha papel constitutivo nas relações de poder, sendo ao mesmo tempo instrumento e objeto de disputa política.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q2 Item 4 (TPS 2003): QUESTÃO 2 (TPS 2003) — Texto "Poder" (1ª parte): trecho de análise política e filosófica sobre as dimensões do poder, suas formas de legitimação e a relação entre discurso, autoridade e dominação nas sociedades modernas. Com base no texto acima, julgue os itens a seguir. [O texto aborda a noção weberiana de dominação legítima como fundamento das modernas democracias representativas.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q2 Item 5 (TPS 2003): QUESTÃO 2 (TPS 2003) — Texto "Poder" (1ª parte): trecho de análise política e filosófica sobre as dimensões do poder, suas formas de legitimação e a relação entre discurso, autoridade e dominação nas sociedades modernas. Com base no texto acima, julgue os itens a seguir. [A análise do texto indica que o poder só se manifesta em contextos institucionais formais, como parlamentos e tribunais.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q3 Item 1 (TPS 2003): QUESTÃO 3 (TPS 2003) — Texto "Poder" (2ª parte): continuação da análise sobre poder, focando nas estratégias discursivas de manutenção e contestação da autoridade, com exemplos históricos de movimentos sociais e retórica política. Com base no texto acima, julgue os itens a seguir. [O texto indica que movimentos sociais utilizam estratégias discursivas para subverter as estruturas de poder vigentes, ressignificando termos e conceitos dominantes.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q3 Item 2 (TPS 2003): QUESTÃO 3 (TPS 2003) — Texto "Poder" (2ª parte): continuação da análise sobre poder, focando nas estratégias discursivas de manutenção e contestação da autoridade, com exemplos históricos de movimentos sociais e retórica política. Com base no texto acima, julgue os itens a seguir. [Segundo o autor, a retórica política serve exclusivamente à manutenção do status quo, não sendo possível seu uso para fins emancipatórios.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q3 Item 3 (TPS 2003): QUESTÃO 3 (TPS 2003) — Texto "Poder" (2ª parte): continuação da análise sobre poder, focando nas estratégias discursivas de manutenção e contestação da autoridade, com exemplos históricos de movimentos sociais e retórica política. Com base no texto acima, julgue os itens a seguir. [O texto emprega a intertextualidade como recurso argumentativo, dialogando com teorias de autores como Foucault e Bourdieu sobre poder e discurso.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q3 Item 4 (TPS 2003): QUESTÃO 3 (TPS 2003) — Texto "Poder" (2ª parte): continuação da análise sobre poder, focando nas estratégias discursivas de manutenção e contestação da autoridade, com exemplos históricos de movimentos sociais e retórica política. Com base no texto acima, julgue os itens a seguir. [A coesão textual é garantida pelo uso de operadores argumentativos que estabelecem relações de causa e consequência entre os parágrafos do texto.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q3 Item 5 (TPS 2003): QUESTÃO 3 (TPS 2003) — Texto "Poder" (2ª parte): continuação da análise sobre poder, focando nas estratégias discursivas de manutenção e contestação da autoridade, com exemplos históricos de movimentos sociais e retórica política. Com base no texto acima, julgue os itens a seguir. [O texto apresenta a resistência ao poder como fenômeno que ocorre apenas em sociedades democráticas, sendo impossível em regimes autoritários.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q4 Item 1 (TPS 2003): QUESTÃO 4 (TPS 2003) — Texto "Poder" (3ª parte): aspectos morfossintáticos e semânticos do texto "Poder", incluindo análise de recursos de coesão referencial, substituição lexical, coerência e progressão temática. Com relação à estrutura linguística do texto, julgue os itens a seguir. [O emprego do pronome "este" em determinado trecho do texto cria referência catafórica, antecipando informação que será desenvolvida a seguir.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q4 Item 2 (TPS 2003): QUESTÃO 4 (TPS 2003) — Texto "Poder" (3ª parte): aspectos morfossintáticos e semânticos do texto "Poder", incluindo análise de recursos de coesão referencial, substituição lexical, coerência e progressão temática. Com relação à estrutura linguística do texto, julgue os itens a seguir. [A nominalização de verbos no texto é recurso que contribui para conferir tom mais formal e abstrato à argumentação do autor.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q4 Item 3 (TPS 2003): QUESTÃO 4 (TPS 2003) — Texto "Poder" (3ª parte): aspectos morfossintáticos e semânticos do texto "Poder", incluindo análise de recursos de coesão referencial, substituição lexical, coerência e progressão temática. Com relação à estrutura linguística do texto, julgue os itens a seguir. [A substituição de termos por sinônimos ou expressões equivalentes ao longo do texto serve exclusivamente à variação estilística, sem função coesiva.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q4 Item 4 (TPS 2003): QUESTÃO 4 (TPS 2003) — Texto "Poder" (3ª parte): aspectos morfossintáticos e semânticos do texto "Poder", incluindo análise de recursos de coesão referencial, substituição lexical, coerência e progressão temática. Com relação à estrutura linguística do texto, julgue os itens a seguir. [As orações subordinadas adverbiais presentes no texto estabelecem relações lógico-semânticas de condição, concessão e finalidade que articulam a argumentação.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q4 Item 5 (TPS 2003): QUESTÃO 4 (TPS 2003) — Texto "Poder" (3ª parte): aspectos morfossintáticos e semânticos do texto "Poder", incluindo análise de recursos de coesão referencial, substituição lexical, coerência e progressão temática. Com relação à estrutura linguística do texto, julgue os itens a seguir. [O uso de aspas em determinadas expressões do texto indica distanciamento crítico do autor em relação aos conceitos assim marcados.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q5 Item 1 (TPS 2003): QUESTÃO 5 (TPS 2003) — Texto "Poder II": novo trecho sobre poder político, abordando a crise de representatividade democrática, o papel da mídia na formação da opinião pública e os desafios do exercício do poder no mundo contemporâneo. Com base no texto acima, julgue os itens a seguir. [O texto argumenta que a mídia contemporânea constitui um quarto poder de facto, capaz de pautar a agenda política e condicionar as decisões governamentais.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q5 Item 2 (TPS 2003): QUESTÃO 5 (TPS 2003) — Texto "Poder II": novo trecho sobre poder político, abordando a crise de representatividade democrática, o papel da mídia na formação da opinião pública e os desafios do exercício do poder no mundo contemporâneo. Com base no texto acima, julgue os itens a seguir. [Segundo o autor, a crise de representatividade democrática é fenômeno exclusivo das democracias latino-americanas, não se verificando nas democracias consolidadas.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q5 Item 3 (TPS 2003): QUESTÃO 5 (TPS 2003) — Texto "Poder II": novo trecho sobre poder político, abordando a crise de representatividade democrática, o papel da mídia na formação da opinião pública e os desafios do exercício do poder no mundo contemporâneo. Com base no texto acima, julgue os itens a seguir. [O texto indica que a opinião pública, tal como construída pela mídia, pode funcionar tanto como mecanismo de controle do poder quanto como instrumento de manipulação.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q5 Item 4 (TPS 2003): QUESTÃO 5 (TPS 2003) — Texto "Poder II": novo trecho sobre poder político, abordando a crise de representatividade democrática, o papel da mídia na formação da opinião pública e os desafios do exercício do poder no mundo contemporâneo. Com base no texto acima, julgue os itens a seguir. [A análise do texto sugere que o exercício do poder no mundo contemporâneo prescinde de legitimidade popular, bastando o controle dos meios de comunicação.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q5 Item 5 (TPS 2003): QUESTÃO 5 (TPS 2003) — Texto "Poder II": novo trecho sobre poder político, abordando a crise de representatividade democrática, o papel da mídia na formação da opinião pública e os desafios do exercício do poder no mundo contemporâneo. Com base no texto acima, julgue os itens a seguir. [O autor defende que a transparência e a prestação de contas são condições necessárias, mas não suficientes, para a legitimidade democrática.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q6 Item 1 (TPS 2003): QUESTÃO 6 (TPS 2003) — Texto "Poder II" (continuação): aspectos gramaticais e de interpretação do texto "Poder II", incluindo questões de morfologia, sintaxe, semântica e recursos argumentativos presentes no trecho. Julgue os itens a seguir, relativos ao texto acima. [A locução verbal utilizada em determinada oração do texto indica aspecto durativo da ação, sugerindo processo ainda em curso no momento da enunciação.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q6 Item 2 (TPS 2003): QUESTÃO 6 (TPS 2003) — Texto "Poder II" (continuação): aspectos gramaticais e de interpretação do texto "Poder II", incluindo questões de morfologia, sintaxe, semântica e recursos argumentativos presentes no trecho. Julgue os itens a seguir, relativos ao texto acima. [O conectivo adversativo utilizado em certa passagem do texto estabelece relação de oposição entre duas proposições igualmente válidas segundo o autor.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q6 Item 3 (TPS 2003): QUESTÃO 6 (TPS 2003) — Texto "Poder II" (continuação): aspectos gramaticais e de interpretação do texto "Poder II", incluindo questões de morfologia, sintaxe, semântica e recursos argumentativos presentes no trecho. Julgue os itens a seguir, relativos ao texto acima. [A estrutura de paralelismo sintático identificada no texto funciona como recurso retórico que confere ênfase e ritmo à argumentação.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q6 Item 4 (TPS 2003): QUESTÃO 6 (TPS 2003) — Texto "Poder II" (continuação): aspectos gramaticais e de interpretação do texto "Poder II", incluindo questões de morfologia, sintaxe, semântica e recursos argumentativos presentes no trecho. Julgue os itens a seguir, relativos ao texto acima. [O uso do modo subjuntivo em determinado período do texto indica que o autor trata o conteúdo da oração como hipótese ou possibilidade, não como certeza.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Português', 'Linguística e texto', 'Q6 Item 5 (TPS 2003): QUESTÃO 6 (TPS 2003) — Texto "Poder II" (continuação): aspectos gramaticais e de interpretação do texto "Poder II", incluindo questões de morfologia, sintaxe, semântica e recursos argumentativos presentes no trecho. Julgue os itens a seguir, relativos ao texto acima. [A progressão temática do texto segue um padrão linear, em que o rema de cada oração torna-se o tema da oração subsequente, garantindo a coerência global.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Diplomacy', 'Q7 Item 1 (TPS 2003): QUESTÃO 7 (TPS 2003) — Text about diplomacy (part 1): excerpt discussing the evolution of modern diplomacy, the role of professional diplomats in international negotiations, bilateral versus multilateral diplomacy, and the impact of globalization on diplomatic practice. Based on the text above, judge the following items as right (C) or wrong (E). [The text implies that the emergence of multilateral diplomacy has rendered bilateral diplomatic channels obsolete in contemporary international relations.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Diplomacy', 'Q7 Item 2 (TPS 2003): QUESTÃO 7 (TPS 2003) — Text about diplomacy (part 1): excerpt discussing the evolution of modern diplomacy, the role of professional diplomats in international negotiations, bilateral versus multilateral diplomacy, and the impact of globalization on diplomatic practice. Based on the text above, judge the following items as right (C) or wrong (E). [According to the text, professional diplomats must combine technical expertise with political acumen, as modern negotiations encompass an ever-broader range of issues.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Diplomacy', 'Q7 Item 3 (TPS 2003): QUESTÃO 7 (TPS 2003) — Text about diplomacy (part 1): excerpt discussing the evolution of modern diplomacy, the role of professional diplomats in international negotiations, bilateral versus multilateral diplomacy, and the impact of globalization on diplomatic practice. Based on the text above, judge the following items as right (C) or wrong (E). [The author argues that globalization has simplified diplomatic practice by reducing the number of actors involved in international negotiations.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Diplomacy', 'Q7 Item 4 (TPS 2003): QUESTÃO 7 (TPS 2003) — Text about diplomacy (part 1): excerpt discussing the evolution of modern diplomacy, the role of professional diplomats in international negotiations, bilateral versus multilateral diplomacy, and the impact of globalization on diplomatic practice. Based on the text above, judge the following items as right (C) or wrong (E). [The text suggests that the distinction between high politics and low politics has become increasingly blurred in contemporary diplomatic practice.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Diplomacy', 'Q7 Item 5 (TPS 2003): QUESTÃO 7 (TPS 2003) — Text about diplomacy (part 1): excerpt discussing the evolution of modern diplomacy, the role of professional diplomats in international negotiations, bilateral versus multilateral diplomacy, and the impact of globalization on diplomatic practice. Based on the text above, judge the following items as right (C) or wrong (E). [According to the passage, the rise of non-state actors has fundamentally undermined the state-centric model of international diplomacy without offering viable alternatives.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Diplomacy', 'Q8 Item 1 (TPS 2003): QUESTÃO 8 (TPS 2003) — Text about diplomacy (part 2): continuation of the text on diplomacy, focusing on the role of summitry, public diplomacy, the use of international organizations as diplomatic forums, and linguistic/grammatical aspects of the passage. Based on the text above, judge the following items as right (C) or wrong (E). [The text indicates that summit meetings between heads of state have become a central feature of contemporary diplomacy, supplementing rather than replacing traditional diplomatic channels.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Diplomacy', 'Q8 Item 2 (TPS 2003): QUESTÃO 8 (TPS 2003) — Text about diplomacy (part 2): continuation of the text on diplomacy, focusing on the role of summitry, public diplomacy, the use of international organizations as diplomatic forums, and linguistic/grammatical aspects of the passage. Based on the text above, judge the following items as right (C) or wrong (E). [The term "public diplomacy" as used in the text refers exclusively to government-to-government communication aimed at influencing foreign policy outcomes.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Diplomacy', 'Q8 Item 3 (TPS 2003): QUESTÃO 8 (TPS 2003) — Text about diplomacy (part 2): continuation of the text on diplomacy, focusing on the role of summitry, public diplomacy, the use of international organizations as diplomatic forums, and linguistic/grammatical aspects of the passage. Based on the text above, judge the following items as right (C) or wrong (E). [The author uses the passive voice extensively throughout the passage to convey an objective, academic tone appropriate to the subject matter.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Diplomacy', 'Q8 Item 4 (TPS 2003): QUESTÃO 8 (TPS 2003) — Text about diplomacy (part 2): continuation of the text on diplomacy, focusing on the role of summitry, public diplomacy, the use of international organizations as diplomatic forums, and linguistic/grammatical aspects of the passage. Based on the text above, judge the following items as right (C) or wrong (E). [According to the text, international organizations serve as arenas where states can pursue their national interests through multilateral negotiation and coalition-building.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Diplomacy', 'Q8 Item 5 (TPS 2003): QUESTÃO 8 (TPS 2003) — Text about diplomacy (part 2): continuation of the text on diplomacy, focusing on the role of summitry, public diplomacy, the use of international organizations as diplomatic forums, and linguistic/grammatical aspects of the passage. Based on the text above, judge the following items as right (C) or wrong (E). [The grammatical structure of the final paragraph suggests a contrast between the idealized vision of diplomatic practice and its actual implementation.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Preventive diplomacy', 'Q9 Item 1 (TPS 2003): QUESTÃO 9 (TPS 2003) — Text about preventive diplomacy (part 1): excerpt discussing the concept of preventive diplomacy as developed by Boutros Boutros-Ghali in the "Agenda for Peace," its instruments, limitations, and role in post-Cold War conflict management. Based on the text above, judge the following items as right (C) or wrong (E). [The concept of preventive diplomacy as described in the text requires early warning, fact-finding missions and confidence-building measures as its core instruments.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Preventive diplomacy', 'Q9 Item 2 (TPS 2003): QUESTÃO 9 (TPS 2003) — Text about preventive diplomacy (part 1): excerpt discussing the concept of preventive diplomacy as developed by Boutros Boutros-Ghali in the "Agenda for Peace," its instruments, limitations, and role in post-Cold War conflict management. Based on the text above, judge the following items as right (C) or wrong (E). [According to the text, preventive diplomacy can only be employed with the explicit consent of all parties to a potential conflict, which severely limits its applicability.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Preventive diplomacy', 'Q9 Item 3 (TPS 2003): QUESTÃO 9 (TPS 2003) — Text about preventive diplomacy (part 1): excerpt discussing the concept of preventive diplomacy as developed by Boutros Boutros-Ghali in the "Agenda for Peace," its instruments, limitations, and role in post-Cold War conflict management. Based on the text above, judge the following items as right (C) or wrong (E). [The text indicates that preventive diplomacy emerged as a dominant paradigm in international security following the end of the Cold War and the expansion of UN peacekeeping operations.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Preventive diplomacy', 'Q9 Item 4 (TPS 2003): QUESTÃO 9 (TPS 2003) — Text about preventive diplomacy (part 1): excerpt discussing the concept of preventive diplomacy as developed by Boutros Boutros-Ghali in the "Agenda for Peace," its instruments, limitations, and role in post-Cold War conflict management. Based on the text above, judge the following items as right (C) or wrong (E). [The passage argues that demilitarized zones and preventive deployments are among the measures that can be used to prevent the escalation of disputes into armed conflicts.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Preventive diplomacy', 'Q9 Item 5 (TPS 2003): QUESTÃO 9 (TPS 2003) — Text about preventive diplomacy (part 1): excerpt discussing the concept of preventive diplomacy as developed by Boutros Boutros-Ghali in the "Agenda for Peace," its instruments, limitations, and role in post-Cold War conflict management. Based on the text above, judge the following items as right (C) or wrong (E). [The author contends that preventive diplomacy has proven equally effective in interstate conflicts and intrastate conflicts driven by ethnic or religious tensions.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Preventive diplomacy', 'Q10 Item 1 (TPS 2003): QUESTÃO 10 (TPS 2003) — Text about preventive diplomacy (part 2): continuation discussing the limitations and critiques of preventive diplomacy, sovereignty concerns, the role of regional organizations, and linguistic/lexical features of the passage. Based on the text above, judge the following items as right (C) or wrong (E). [The text suggests that the principle of state sovereignty constitutes the primary obstacle to the effective implementation of preventive diplomacy in intrastate conflicts.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Preventive diplomacy', 'Q10 Item 2 (TPS 2003): QUESTÃO 10 (TPS 2003) — Text about preventive diplomacy (part 2): continuation discussing the limitations and critiques of preventive diplomacy, sovereignty concerns, the role of regional organizations, and linguistic/lexical features of the passage. Based on the text above, judge the following items as right (C) or wrong (E). [According to the passage, regional organizations such as the OAS and OSCE have been consistently more effective than the UN in implementing preventive diplomacy measures.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Preventive diplomacy', 'Q10 Item 3 (TPS 2003): QUESTÃO 10 (TPS 2003) — Text about preventive diplomacy (part 2): continuation discussing the limitations and critiques of preventive diplomacy, sovereignty concerns, the role of regional organizations, and linguistic/lexical features of the passage. Based on the text above, judge the following items as right (C) or wrong (E). [The use of modal verbs throughout the text reflects the author''s intent to convey the conditional and contingent nature of preventive diplomacy''s effectiveness.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Preventive diplomacy', 'Q10 Item 4 (TPS 2003): QUESTÃO 10 (TPS 2003) — Text about preventive diplomacy (part 2): continuation discussing the limitations and critiques of preventive diplomacy, sovereignty concerns, the role of regional organizations, and linguistic/lexical features of the passage. Based on the text above, judge the following items as right (C) or wrong (E). [The text explicitly endorses humanitarian intervention as a legitimate form of preventive diplomacy when negotiated measures have failed to prevent imminent atrocities.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Inglês', 'Reading comprehension — Preventive diplomacy', 'Q10 Item 5 (TPS 2003): QUESTÃO 10 (TPS 2003) — Text about preventive diplomacy (part 2): continuation discussing the limitations and critiques of preventive diplomacy, sovereignty concerns, the role of regional organizations, and linguistic/lexical features of the passage. Based on the text above, judge the following items as right (C) or wrong (E). [The passage indicates that early warning systems, while theoretically valuable, have rarely translated into timely preventive action due to political constraints within the UN Security Council.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Política Internacional', 'MERCOSUL e integração regional', 'Q11 Item 1 (TPS 2003): QUESTÃO 11 (TPS 2003) — MERCOSUL e globalização: questão sobre o processo de integração regional sul-americana no contexto da globalização econômica, abordando a evolução institucional do MERCOSUL, suas crises, o impacto das políticas econômicas dos anos 1990 e os desafios para o aprofundamento da integração. Acerca do MERCOSUL e da globalização, julgue os itens a seguir. [O MERCOSUL, criado pelo Tratado de Assunção em 1991, atingiu plenamente os objetivos de mercado comum previstos em seu tratado constitutivo, incluindo livre circulação de fatores de produção.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Política Internacional', 'MERCOSUL e integração regional', 'Q11 Item 2 (TPS 2003): QUESTÃO 11 (TPS 2003) — MERCOSUL e globalização: questão sobre o processo de integração regional sul-americana no contexto da globalização econômica, abordando a evolução institucional do MERCOSUL, suas crises, o impacto das políticas econômicas dos anos 1990 e os desafios para o aprofundamento da integração. Acerca do MERCOSUL e da globalização, julgue os itens a seguir. [A crise argentina de 2001-2002 demonstrou a vulnerabilidade dos países do MERCOSUL às turbulências financeiras internacionais e os limites da integração monetária regional.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Política Internacional', 'MERCOSUL e integração regional', 'Q11 Item 3 (TPS 2003): QUESTÃO 11 (TPS 2003) — MERCOSUL e globalização: questão sobre o processo de integração regional sul-americana no contexto da globalização econômica, abordando a evolução institucional do MERCOSUL, suas crises, o impacto das políticas econômicas dos anos 1990 e os desafios para o aprofundamento da integração. Acerca do MERCOSUL e da globalização, julgue os itens a seguir. [A adoção de uma tarifa externa comum pelo MERCOSUL constituiu passo relevante para a consolidação de uma união aduaneira, embora com importantes exceções setoriais.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Política Internacional', 'MERCOSUL e integração regional', 'Q11 Item 4 (TPS 2003): QUESTÃO 11 (TPS 2003) — MERCOSUL e globalização: questão sobre o processo de integração regional sul-americana no contexto da globalização econômica, abordando a evolução institucional do MERCOSUL, suas crises, o impacto das políticas econômicas dos anos 1990 e os desafios para o aprofundamento da integração. Acerca do MERCOSUL e da globalização, julgue os itens a seguir. [O Protocolo de Ouro Preto de 1994 conferiu ao MERCOSUL personalidade jurídica internacional e estabeleceu sua estrutura institucional definitiva, incluindo um parlamento regional com poderes legislativos.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Política Internacional', 'MERCOSUL e integração regional', 'Q11 Item 5 (TPS 2003): QUESTÃO 11 (TPS 2003) — MERCOSUL e globalização: questão sobre o processo de integração regional sul-americana no contexto da globalização econômica, abordando a evolução institucional do MERCOSUL, suas crises, o impacto das políticas econômicas dos anos 1990 e os desafios para o aprofundamento da integração. Acerca do MERCOSUL e da globalização, julgue os itens a seguir. [No contexto da globalização, a integração regional é apresentada no debate acadêmico como estratégia de inserção coletiva na economia mundial, capaz de aumentar o poder de barganha dos países membros.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Política Internacional', 'Conferências internacionais da ONU', 'Q12 Item 1 (TPS 2003): QUESTÃO 12 (TPS 2003) — Conferências internacionais da ONU nos anos 1990: questão sobre o ciclo de grandes conferências das Nações Unidas realizadas na década de 1990, incluindo Rio-92, Viena 1993, Cairo 1994, Copenhague 1995, Beijing 1995 e Habitat II 1996, e seus impactos na agenda internacional. Com relação às conferências internacionais da ONU realizadas nos anos 1990, julgue os itens a seguir. [A Conferência de Viena de 1993 sobre Direitos Humanos reafirmou a universalidade, indivisibilidade e interdependência dos direitos humanos, consolidando o conceito de que os direitos civis e políticos têm primazia sobre os direitos econômicos, sociais e culturais.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Política Internacional', 'Conferências internacionais da ONU', 'Q12 Item 2 (TPS 2003): QUESTÃO 12 (TPS 2003) — Conferências internacionais da ONU nos anos 1990: questão sobre o ciclo de grandes conferências das Nações Unidas realizadas na década de 1990, incluindo Rio-92, Viena 1993, Cairo 1994, Copenhague 1995, Beijing 1995 e Habitat II 1996, e seus impactos na agenda internacional. Com relação às conferências internacionais da ONU realizadas nos anos 1990, julgue os itens a seguir. [A Agenda 21, adotada na Conferência do Rio de 1992, estabeleceu um programa de ação global para o desenvolvimento sustentável, atribuindo responsabilidades diferenciadas a países desenvolvidos e em desenvolvimento.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Política Internacional', 'Conferências internacionais da ONU', 'Q12 Item 3 (TPS 2003): QUESTÃO 12 (TPS 2003) — Conferências internacionais da ONU nos anos 1990: questão sobre o ciclo de grandes conferências das Nações Unidas realizadas na década de 1990, incluindo Rio-92, Viena 1993, Cairo 1994, Copenhague 1995, Beijing 1995 e Habitat II 1996, e seus impactos na agenda internacional. Com relação às conferências internacionais da ONU realizadas nos anos 1990, julgue os itens a seguir. [A Conferência Internacional sobre População e Desenvolvimento do Cairo de 1994 foi marcada por controvérsias em torno de questões relativas à saúde reprodutiva e direitos da mulher, com posições divergentes entre países ocidentais e nações de tradição islâmica.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Política Internacional', 'Conferências internacionais da ONU', 'Q12 Item 4 (TPS 2003): QUESTÃO 12 (TPS 2003) — Conferências internacionais da ONU nos anos 1990: questão sobre o ciclo de grandes conferências das Nações Unidas realizadas na década de 1990, incluindo Rio-92, Viena 1993, Cairo 1994, Copenhague 1995, Beijing 1995 e Habitat II 1996, e seus impactos na agenda internacional. Com relação às conferências internacionais da ONU realizadas nos anos 1990, julgue os itens a seguir. [O conceito de "responsabilidade de proteger," formulado no âmbito das conferências da ONU nos anos 1990, foi formalmente incorporado ao direito internacional costumeiro pela Declaração do Milênio de 2000.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Política Internacional', 'Conferências internacionais da ONU', 'Q12 Item 5 (TPS 2003): QUESTÃO 12 (TPS 2003) — Conferências internacionais da ONU nos anos 1990: questão sobre o ciclo de grandes conferências das Nações Unidas realizadas na década de 1990, incluindo Rio-92, Viena 1993, Cairo 1994, Copenhague 1995, Beijing 1995 e Habitat II 1996, e seus impactos na agenda internacional. Com relação às conferências internacionais da ONU realizadas nos anos 1990, julgue os itens a seguir. [A IV Conferência Mundial sobre a Mulher realizada em Beijing em 1995 adotou a Plataforma de Ação de Beijing, documento que incorporou o conceito de mainstreaming de gênero como estratégia para a promoção da igualdade.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Política Internacional', 'China e integração à OMC', 'Q13 Item 1 (TPS 2003): QUESTÃO 13 (TPS 2003) — China e a OMC: questão sobre a adesão da China à Organização Mundial do Comércio em 2001, os termos negociados para sua entrada, o impacto no comércio mundial, as transformações econômicas chinesas e as implicações geopolíticas da ascensão econômica da China. A respeito da China e de sua inserção na OMC, julgue os itens a seguir. [A adesão da China à OMC em 2001, após quinze anos de negociações, foi condicionada a compromissos de abertura de mercados, redução de tarifas e eliminação de subsídios às exportações agrícolas em prazo imediato.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Política Internacional', 'China e integração à OMC', 'Q13 Item 2 (TPS 2003): QUESTÃO 13 (TPS 2003) — China e a OMC: questão sobre a adesão da China à Organização Mundial do Comércio em 2001, os termos negociados para sua entrada, o impacto no comércio mundial, as transformações econômicas chinesas e as implicações geopolíticas da ascensão econômica da China. A respeito da China e de sua inserção na OMC, julgue os itens a seguir. [O crescimento econômico chinês nos anos 1990 e 2000 baseou-se predominantemente na expansão das exportações manufatureiras, beneficiadas por baixos custos de mão de obra e pela política cambial de desvalorização do renminbi.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Política Internacional', 'China e integração à OMC', 'Q13 Item 3 (TPS 2003): QUESTÃO 13 (TPS 2003) — China e a OMC: questão sobre a adesão da China à Organização Mundial do Comércio em 2001, os termos negociados para sua entrada, o impacto no comércio mundial, as transformações econômicas chinesas e as implicações geopolíticas da ascensão econômica da China. A respeito da China e de sua inserção na OMC, julgue os itens a seguir. [A ascensão econômica da China suscitou debates sobre sua capacidade de se tornar um "stakeholder responsável" na ordem internacional, integrando-se às normas e instituições do sistema multilateral sem questioná-las.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Política Internacional', 'China e integração à OMC', 'Q13 Item 4 (TPS 2003): QUESTÃO 13 (TPS 2003) — China e a OMC: questão sobre a adesão da China à Organização Mundial do Comércio em 2001, os termos negociados para sua entrada, o impacto no comércio mundial, as transformações econômicas chinesas e as implicações geopolíticas da ascensão econômica da China. A respeito da China e de sua inserção na OMC, julgue os itens a seguir. [A China manteve, após sua adesão à OMC, regime de economia planificada centralizada, sem permitir mecanismos de mercado no setor industrial, o que gerou disputas com seus parceiros comerciais no mecanismo de solução de controvérsias da organização.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Política Internacional', 'China e integração à OMC', 'Q13 Item 5 (TPS 2003): QUESTÃO 13 (TPS 2003) — China e a OMC: questão sobre a adesão da China à Organização Mundial do Comércio em 2001, os termos negociados para sua entrada, o impacto no comércio mundial, as transformações econômicas chinesas e as implicações geopolíticas da ascensão econômica da China. A respeito da China e de sua inserção na OMC, julgue os itens a seguir. [O ingresso da China na OMC foi visto por países em desenvolvimento como potencial ameaça à sua participação nos mercados de manufaturas, especialmente no setor têxtil e de vestuário.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Política Internacional', 'Paradigmas de política externa', 'Q14 Item 1 (TPS 2003): QUESTÃO 14 (TPS 2003) — Estado desenvolvimentista e política externa: questão sobre o conceito de Estado desenvolvimentista e suas implicações para a política externa, comparando experiências asiáticas (Japão, Coreia do Sul) e latino-americanas, e discutindo o debate sobre neoliberalismo versus desenvolvimentismo. No que se refere ao Estado desenvolvimentista e à política externa, julgue os itens a seguir. [O modelo do Estado desenvolvimentista, identificado nas experiências do Japão e Coreia do Sul no pós-guerra, caracteriza-se pela intervenção estatal estratégica na economia, com planejamento industrial e promoção de setores considerados prioritários para o desenvolvimento nacional.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Política Internacional', 'Paradigmas de política externa', 'Q14 Item 2 (TPS 2003): QUESTÃO 14 (TPS 2003) — Estado desenvolvimentista e política externa: questão sobre o conceito de Estado desenvolvimentista e suas implicações para a política externa, comparando experiências asiáticas (Japão, Coreia do Sul) e latino-americanas, e discutindo o debate sobre neoliberalismo versus desenvolvimentismo. No que se refere ao Estado desenvolvimentista e à política externa, julgue os itens a seguir. [A experiência desenvolvimentista brasileira do período 1950-1980, marcada pela industrialização por substituição de importações, produziu resultados análogos aos dos tigres asiáticos em termos de competitividade exportadora e inserção nos mercados internacionais.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Política Internacional', 'Paradigmas de política externa', 'Q14 Item 3 (TPS 2003): QUESTÃO 14 (TPS 2003) — Estado desenvolvimentista e política externa: questão sobre o conceito de Estado desenvolvimentista e suas implicações para a política externa, comparando experiências asiáticas (Japão, Coreia do Sul) e latino-americanas, e discutindo o debate sobre neoliberalismo versus desenvolvimentismo. No que se refere ao Estado desenvolvimentista e à política externa, julgue os itens a seguir. [O Consenso de Washington, formulado nos anos 1980, propugnava a retirada do Estado da atividade econômica como condição para a estabilização macroeconômica e o crescimento sustentado dos países em desenvolvimento.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Política Internacional', 'Paradigmas de política externa', 'Q14 Item 4 (TPS 2003): QUESTÃO 14 (TPS 2003) — Estado desenvolvimentista e política externa: questão sobre o conceito de Estado desenvolvimentista e suas implicações para a política externa, comparando experiências asiáticas (Japão, Coreia do Sul) e latino-americanas, e discutindo o debate sobre neoliberalismo versus desenvolvimentismo. No que se refere ao Estado desenvolvimentista e à política externa, julgue os itens a seguir. [A política externa dos países desenvolvimentistas asiáticos caracterizou-se pelo alinhamento incondicional aos Estados Unidos durante a Guerra Fria, o que lhes garantiu acesso privilegiado ao mercado norte-americano e às transferências de tecnologia.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Política Internacional', 'Paradigmas de política externa', 'Q14 Item 5 (TPS 2003): QUESTÃO 14 (TPS 2003) — Estado desenvolvimentista e política externa: questão sobre o conceito de Estado desenvolvimentista e suas implicações para a política externa, comparando experiências asiáticas (Japão, Coreia do Sul) e latino-americanas, e discutindo o debate sobre neoliberalismo versus desenvolvimentismo. No que se refere ao Estado desenvolvimentista e à política externa, julgue os itens a seguir. [O debate contemporâneo sobre o papel do Estado no desenvolvimento retomou elementos do desenvolvimentismo clássico, incorporando preocupações com sustentabilidade ambiental, inclusão social e inserção competitiva na economia do conhecimento.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'História', 'História do século XX', 'Q15 Item 1 (TPS 2003): QUESTÃO 15 (TPS 2003) — Hobsbawm e o "século XX curto": questão baseada na obra "Era dos Extremos" de Eric Hobsbawm, abordando sua interpretação do século XX como "século curto" (1914-1991), a periodização em "Era da Catástrofe," "Era de Ouro" e "Desmoronamento," e os eventos globais que marcaram cada fase. Acerca da interpretação histórica do século XX e da obra de Hobsbawm, julgue os itens a seguir. [Hobsbawm designa o período 1914-1991 como o "breve século XX," caracterizado pela catástrofe inicial das duas guerras mundiais, seguida de um período de crescimento e estabilidade e, por fim, de crise e incerteza.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'História', 'História do século XX', 'Q15 Item 2 (TPS 2003): QUESTÃO 15 (TPS 2003) — Hobsbawm e o "século XX curto": questão baseada na obra "Era dos Extremos" de Eric Hobsbawm, abordando sua interpretação do século XX como "século curto" (1914-1991), a periodização em "Era da Catástrofe," "Era de Ouro" e "Desmoronamento," e os eventos globais que marcaram cada fase. Acerca da interpretação histórica do século XX e da obra de Hobsbawm, julgue os itens a seguir. [Segundo Hobsbawm, a "Era de Ouro" do capitalismo (1947-1973) representou o mais extraordinário período de crescimento econômico da história mundial, com expansão sem precedentes do bem-estar social nos países desenvolvidos.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'História', 'História do século XX', 'Q15 Item 3 (TPS 2003): QUESTÃO 15 (TPS 2003) — Hobsbawm e o "século XX curto": questão baseada na obra "Era dos Extremos" de Eric Hobsbawm, abordando sua interpretação do século XX como "século curto" (1914-1991), a periodização em "Era da Catástrofe," "Era de Ouro" e "Desmoronamento," e os eventos globais que marcaram cada fase. Acerca da interpretação histórica do século XX e da obra de Hobsbawm, julgue os itens a seguir. [A interpretação de Hobsbawm do século XX é marcada por uma perspectiva marxista que atribui à luta de classes o papel determinante na configuração dos eventos históricos, minimizando o papel dos indivíduos e das contingências.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'História', 'História do século XX', 'Q15 Item 4 (TPS 2003): QUESTÃO 15 (TPS 2003) — Hobsbawm e o "século XX curto": questão baseada na obra "Era dos Extremos" de Eric Hobsbawm, abordando sua interpretação do século XX como "século curto" (1914-1991), a periodização em "Era da Catástrofe," "Era de Ouro" e "Desmoronamento," e os eventos globais que marcaram cada fase. Acerca da interpretação histórica do século XX e da obra de Hobsbawm, julgue os itens a seguir. [Para Hobsbawm, a dissolução da URSS em 1991 representou o colapso do projeto socialista soviético, mas não o "fim da história" nem a vitória definitiva do capitalismo liberal sobre todas as alternativas possíveis.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'História', 'História do século XX', 'Q15 Item 5 (TPS 2003): QUESTÃO 15 (TPS 2003) — Hobsbawm e o "século XX curto": questão baseada na obra "Era dos Extremos" de Eric Hobsbawm, abordando sua interpretação do século XX como "século curto" (1914-1991), a periodização em "Era da Catástrofe," "Era de Ouro" e "Desmoronamento," e os eventos globais que marcaram cada fase. Acerca da interpretação histórica do século XX e da obra de Hobsbawm, julgue os itens a seguir. [A "Era da Catástrofe" de Hobsbawm compreende o período das duas guerras mundiais e a Grande Depressão, durante o qual a ordem liberal do século XIX foi destruída e o futuro do capitalismo tornou-se incerto.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'História', 'Guerra Fria', 'Q16 Item 1 (TPS 2003): QUESTÃO 16 (TPS 2003) — Guerra Fria: questão sobre as origens, dinâmica e legado da Guerra Fria, abordando a bipolaridade EUA-URSS, a corrida armamentista, os conflitos regionais por procuração, as crises nucleares e o impacto da Guerra Fria na política dos países do Terceiro Mundo. Com relação à Guerra Fria e seus desdobramentos, julgue os itens a seguir. [A doutrina Truman (1947) e o Plano Marshall representaram a formalização da estratégia de contenção americana frente à expansão soviética, definindo os parâmetros da política externa dos EUA por quatro décadas.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'História', 'Guerra Fria', 'Q16 Item 2 (TPS 2003): QUESTÃO 16 (TPS 2003) — Guerra Fria: questão sobre as origens, dinâmica e legado da Guerra Fria, abordando a bipolaridade EUA-URSS, a corrida armamentista, os conflitos regionais por procuração, as crises nucleares e o impacto da Guerra Fria na política dos países do Terceiro Mundo. Com relação à Guerra Fria e seus desdobramentos, julgue os itens a seguir. [A crise dos mísseis de Cuba (1962) demonstrou que a lógica de dissuasão nuclear mútua (MAD) era suficiente para impedir qualquer confronto militar direto entre as superpotências, confirmando a estabilidade do equilíbrio bipolar.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'História', 'Guerra Fria', 'Q16 Item 3 (TPS 2003): QUESTÃO 16 (TPS 2003) — Guerra Fria: questão sobre as origens, dinâmica e legado da Guerra Fria, abordando a bipolaridade EUA-URSS, a corrida armamentista, os conflitos regionais por procuração, as crises nucleares e o impacto da Guerra Fria na política dos países do Terceiro Mundo. Com relação à Guerra Fria e seus desdobramentos, julgue os itens a seguir. [O Movimento dos Não Alinhados, fundado em Bandung em 1955, constituiu tentativa dos países do Terceiro Mundo de escapar à lógica bipolar da Guerra Fria, afirmando uma agenda própria centrada no anticolonialismo e no desenvolvimento.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'História', 'Guerra Fria', 'Q16 Item 4 (TPS 2003): QUESTÃO 16 (TPS 2003) — Guerra Fria: questão sobre as origens, dinâmica e legado da Guerra Fria, abordando a bipolaridade EUA-URSS, a corrida armamentista, os conflitos regionais por procuração, as crises nucleares e o impacto da Guerra Fria na política dos países do Terceiro Mundo. Com relação à Guerra Fria e seus desdobramentos, julgue os itens a seguir. [A détente dos anos 1970 resultou em acordos significativos de controle de armamentos (SALT I e II), mas foi revertida pelo intervencionismo soviético no Afeganistão e pela ascensão de Reagan, que reinaugurou uma fase de confrontação ideológica e militar.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'História', 'Guerra Fria', 'Q16 Item 5 (TPS 2003): QUESTÃO 16 (TPS 2003) — Guerra Fria: questão sobre as origens, dinâmica e legado da Guerra Fria, abordando a bipolaridade EUA-URSS, a corrida armamentista, os conflitos regionais por procuração, as crises nucleares e o impacto da Guerra Fria na política dos países do Terceiro Mundo. Com relação à Guerra Fria e seus desdobramentos, julgue os itens a seguir. [A queda do Muro de Berlim em 1989 e a reunificação alemã foram resultados diretos da política de glasnost e perestroika de Gorbachev, que tinha como objetivo reformar o sistema soviético para salvá-lo, não para desmontá-lo.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'História', 'República Brasileira', 'Q17 Item 1 (TPS 2003): QUESTÃO 17 (TPS 2003) — História da República Brasileira: questão sobre os principais momentos da história política brasileira desde a Proclamação da República em 1889 até a redemocratização, abordando a República Velha, a Revolução de 30, o Estado Novo, a experiência democrática de 1946-1964, o regime militar e a transição para a democracia. Acerca da história da República Brasileira, julgue os itens a seguir. [A política dos governadores durante a República Velha (1894-1930) baseava-se em acordo entre as elites estaduais e o governo federal, garantindo apoio mútuo mediante a distribuição de cargos e recursos, o que excluía sistematicamente as classes trabalhadoras urbanas da representação política.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'História', 'República Brasileira', 'Q17 Item 2 (TPS 2003): QUESTÃO 17 (TPS 2003) — História da República Brasileira: questão sobre os principais momentos da história política brasileira desde a Proclamação da República em 1889 até a redemocratização, abordando a República Velha, a Revolução de 30, o Estado Novo, a experiência democrática de 1946-1964, o regime militar e a transição para a democracia. Acerca da história da República Brasileira, julgue os itens a seguir. [A Revolução de 1930, liderada por Getúlio Vargas, representou ruptura definitiva com as oligarquias rurais da República Velha, promovendo a imediata democratização e a incorporação política das massas urbanas ao sistema representativo.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'História', 'República Brasileira', 'Q17 Item 3 (TPS 2003): QUESTÃO 17 (TPS 2003) — História da República Brasileira: questão sobre os principais momentos da história política brasileira desde a Proclamação da República em 1889 até a redemocratização, abordando a República Velha, a Revolução de 30, o Estado Novo, a experiência democrática de 1946-1964, o regime militar e a transição para a democracia. Acerca da história da República Brasileira, julgue os itens a seguir. [O Estado Novo (1937-1945) caracterizou-se pela centralização política, supressão dos partidos e do Congresso, intervenção estatal na economia e promoção do nacionalismo, aproximando-se dos regimes corporativistas europeus do período.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'História', 'República Brasileira', 'Q17 Item 4 (TPS 2003): QUESTÃO 17 (TPS 2003) — História da República Brasileira: questão sobre os principais momentos da história política brasileira desde a Proclamação da República em 1889 até a redemocratização, abordando a República Velha, a Revolução de 30, o Estado Novo, a experiência democrática de 1946-1964, o regime militar e a transição para a democracia. Acerca da história da República Brasileira, julgue os itens a seguir. [O golpe militar de 1964 contou com apoio de segmentos das classes médias, do empresariado e da Igreja Católica, que temiam uma guinada comunista sob o governo Goulart, num contexto marcado pela polarização da Guerra Fria.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'História', 'República Brasileira', 'Q17 Item 5 (TPS 2003): QUESTÃO 17 (TPS 2003) — História da República Brasileira: questão sobre os principais momentos da história política brasileira desde a Proclamação da República em 1889 até a redemocratização, abordando a República Velha, a Revolução de 30, o Estado Novo, a experiência democrática de 1946-1964, o regime militar e a transição para a democracia. Acerca da história da República Brasileira, julgue os itens a seguir. [A transição para a democracia no Brasil (1974-1985) seguiu o modelo de "distensão lenta, gradual e segura" propugnado pelo governo Geisel, mantendo as Forças Armadas no controle do ritmo da abertura política até a eleição de Tancredo Neves pelo Colégio Eleitoral.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'História', 'Política Externa Brasileira', 'Q18 Item 1 (TPS 2003): QUESTÃO 18 (TPS 2003) — Política Externa Brasileira: questão sobre a evolução da política externa do Brasil, desde o Barão do Rio Branco até o final do século XX, abordando os paradigmas de inserção internacional, as alianças estratégicas, o papel do Itamaraty e as continuidades e mudanças na diplomacia brasileira. Julgue os itens a seguir, relativos à política externa brasileira. [O Barão do Rio Branco, à frente do Ministério das Relações Exteriores entre 1902 e 1912, consolidou as fronteiras brasileiras mediante negociações diplomáticas e arbitragens internacionais, estabelecendo padrões de atuação que influenciaram duradouramente a diplomacia do país.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'História', 'Política Externa Brasileira', 'Q18 Item 2 (TPS 2003): QUESTÃO 18 (TPS 2003) — Política Externa Brasileira: questão sobre a evolução da política externa do Brasil, desde o Barão do Rio Branco até o final do século XX, abordando os paradigmas de inserção internacional, as alianças estratégicas, o papel do Itamaraty e as continuidades e mudanças na diplomacia brasileira. Julgue os itens a seguir, relativos à política externa brasileira. [A Política Externa Independente, formulada durante os governos Jânio Quadros e João Goulart (1961-1964), representou ruptura com o alinhamento automático aos EUA e buscou diversificar as parcerias do Brasil, incluindo relações com países socialistas e países afro-asiáticos.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'História', 'Política Externa Brasileira', 'Q18 Item 3 (TPS 2003): QUESTÃO 18 (TPS 2003) — Política Externa Brasileira: questão sobre a evolução da política externa do Brasil, desde o Barão do Rio Branco até o final do século XX, abordando os paradigmas de inserção internacional, as alianças estratégicas, o papel do Itamaraty e as continuidades e mudanças na diplomacia brasileira. Julgue os itens a seguir, relativos à política externa brasileira. [O Brasil praticou política externa de elevado grau de autonomia logo após a Revolução de 1930, rompendo com os vínculos históricos com o Reino Unido e alinhando-se precocemente com os Estados Unidos como potência hegemônica do século XX.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'História', 'Política Externa Brasileira', 'Q18 Item 4 (TPS 2003): QUESTÃO 18 (TPS 2003) — Política Externa Brasileira: questão sobre a evolução da política externa do Brasil, desde o Barão do Rio Branco até o final do século XX, abordando os paradigmas de inserção internacional, as alianças estratégicas, o papel do Itamaraty e as continuidades e mudanças na diplomacia brasileira. Julgue os itens a seguir, relativos à política externa brasileira. [O pragmatismo responsável e ecumênico da diplomacia do governo Geisel (1974-1979) buscou diversificar as parcerias externas do Brasil, incluindo o reconhecimento das independências africanas e o estabelecimento de relações com a República Popular da China.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'História', 'Política Externa Brasileira', 'Q18 Item 5 (TPS 2003): QUESTÃO 18 (TPS 2003) — Política Externa Brasileira: questão sobre a evolução da política externa do Brasil, desde o Barão do Rio Branco até o final do século XX, abordando os paradigmas de inserção internacional, as alianças estratégicas, o papel do Itamaraty e as continuidades e mudanças na diplomacia brasileira. Julgue os itens a seguir, relativos à política externa brasileira. [O universalismo da política externa brasileira dos anos 1990 traduziu-se na participação ativa em foros multilaterais, incluindo as negociações da Rodada Uruguai do GATT e a adesão aos principais regimes internacionais de não proliferação nuclear.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Geografia', 'Globalização econômica', 'Q19 Item 1 (TPS 2003): QUESTÃO 19 (TPS 2003) — Montadoras e globalização produtiva: questão sobre a expansão das montadoras automobilísticas para países emergentes, especialmente a China, no contexto da globalização produtiva, abordando as estratégias de localização industrial, os impactos nos países receptores e as novas geografias da produção global. Acerca da globalização produtiva e da indústria automobilística, julgue os itens a seguir. [A expansão das montadoras automobilísticas para a China nos anos 1990 e 2000 foi motivada pelo enorme mercado consumidor potencial, pelos baixos custos de produção e pelas políticas de atração de investimento estrangeiro do governo chinês.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Geografia', 'Globalização econômica', 'Q19 Item 2 (TPS 2003): QUESTÃO 19 (TPS 2003) — Montadoras e globalização produtiva: questão sobre a expansão das montadoras automobilísticas para países emergentes, especialmente a China, no contexto da globalização produtiva, abordando as estratégias de localização industrial, os impactos nos países receptores e as novas geografias da produção global. Acerca da globalização produtiva e da indústria automobilística, julgue os itens a seguir. [As montadoras multinacionais que se instalaram na China foram obrigadas, em sua maioria, a operar em joint ventures com empresas estatais chinesas, o que permitiu a transferência de tecnologia e a formação de indústria automobilística nacional.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Geografia', 'Globalização econômica', 'Q19 Item 3 (TPS 2003): QUESTÃO 19 (TPS 2003) — Montadoras e globalização produtiva: questão sobre a expansão das montadoras automobilísticas para países emergentes, especialmente a China, no contexto da globalização produtiva, abordando as estratégias de localização industrial, os impactos nos países receptores e as novas geografias da produção global. Acerca da globalização produtiva e da indústria automobilística, julgue os itens a seguir. [A globalização produtiva na indústria automobilística resultou em fragmentação das cadeias de valor, com diferentes etapas da produção localizadas em países distintos conforme suas vantagens comparativas em custos e habilidades.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Geografia', 'Globalização econômica', 'Q19 Item 4 (TPS 2003): QUESTÃO 19 (TPS 2003) — Montadoras e globalização produtiva: questão sobre a expansão das montadoras automobilísticas para países emergentes, especialmente a China, no contexto da globalização produtiva, abordando as estratégias de localização industrial, os impactos nos países receptores e as novas geografias da produção global. Acerca da globalização produtiva e da indústria automobilística, julgue os itens a seguir. [A instalação de montadoras em países emergentes como Brasil, México e China é fenômeno associado exclusivamente ao período pós-2000, não havendo precedentes de deslocalização industrial automobilística anteriores à globalização financeira dos anos 1990.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Geografia', 'Globalização econômica', 'Q19 Item 5 (TPS 2003): QUESTÃO 19 (TPS 2003) — Montadoras e globalização produtiva: questão sobre a expansão das montadoras automobilísticas para países emergentes, especialmente a China, no contexto da globalização produtiva, abordando as estratégias de localização industrial, os impactos nos países receptores e as novas geografias da produção global. Acerca da globalização produtiva e da indústria automobilística, julgue os itens a seguir. [A China tornou-se, na primeira década do século XXI, o maior mercado automobilístico do mundo, superando os Estados Unidos em volume de vendas anuais de veículos novos.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Geografia', 'América Latina e recursos naturais', 'Q20 Item 1 (TPS 2003): QUESTÃO 20 (TPS 2003) — América Latina e recursos naturais: questão sobre a dotação de recursos naturais da América Latina, sua relação com o desenvolvimento econômico regional, os conflitos em torno da gestão desses recursos, a questão da "maldição dos recursos" e as disputas geopolíticas associadas. Acerca dos recursos naturais na América Latina e seus impactos, julgue os itens a seguir. [A América Latina possui extraordinária dotação de recursos naturais, incluindo as maiores reservas mundiais de petróleo (Venezuela), minérios estratégicos e biodiversidade, configurando uma vantagem comparativa que se traduz em desenvolvimento sustentado.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Geografia', 'América Latina e recursos naturais', 'Q20 Item 2 (TPS 2003): QUESTÃO 20 (TPS 2003) — América Latina e recursos naturais: questão sobre a dotação de recursos naturais da América Latina, sua relação com o desenvolvimento econômico regional, os conflitos em torno da gestão desses recursos, a questão da "maldição dos recursos" e as disputas geopolíticas associadas. Acerca dos recursos naturais na América Latina e seus impactos, julgue os itens a seguir. [O conceito de "maldição dos recursos" descreve o paradoxo pelo qual países ricos em recursos naturais tendem a apresentar menor crescimento econômico, maior desigualdade e instituições mais frágeis do que países com menor dotação de recursos.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Geografia', 'América Latina e recursos naturais', 'Q20 Item 3 (TPS 2003): QUESTÃO 20 (TPS 2003) — América Latina e recursos naturais: questão sobre a dotação de recursos naturais da América Latina, sua relação com o desenvolvimento econômico regional, os conflitos em torno da gestão desses recursos, a questão da "maldição dos recursos" e as disputas geopolíticas associadas. Acerca dos recursos naturais na América Latina e seus impactos, julgue os itens a seguir. [As disputas em torno do controle dos recursos naturais na América Latina envolvem tanto atores domésticos (governos, empresas estatais, comunidades locais) quanto externos (empresas multinacionais, governos de países consumidores), gerando conflitos socioambientais.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Geografia', 'América Latina e recursos naturais', 'Q20 Item 4 (TPS 2003): QUESTÃO 20 (TPS 2003) — América Latina e recursos naturais: questão sobre a dotação de recursos naturais da América Latina, sua relação com o desenvolvimento econômico regional, os conflitos em torno da gestão desses recursos, a questão da "maldição dos recursos" e as disputas geopolíticas associadas. Acerca dos recursos naturais na América Latina e seus impactos, julgue os itens a seguir. [A exploração dos recursos naturais latino-americanos foi historicamente marcada por padrões de enclave, com baixa integração às economias nacionais, elevada remessa de lucros ao exterior e escassa geração de encadeamentos produtivos locais.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Geografia', 'América Latina e recursos naturais', 'Q20 Item 5 (TPS 2003): QUESTÃO 20 (TPS 2003) — América Latina e recursos naturais: questão sobre a dotação de recursos naturais da América Latina, sua relação com o desenvolvimento econômico regional, os conflitos em torno da gestão desses recursos, a questão da "maldição dos recursos" e as disputas geopolíticas associadas. Acerca dos recursos naturais na América Latina e seus impactos, julgue os itens a seguir. [A Bacia Amazônica constitui o principal reservatório de biodiversidade do planeta e abriga significativa parcela das reservas mundiais de água doce, sendo sua preservação reconhecida internacionalmente como questão de interesse global e não apenas nacional.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Geografia', 'Questão ambiental', 'Q21 Item 1 (TPS 2003): QUESTÃO 21 (TPS 2003) — Ecologia e questão ambiental no Brasil: questão sobre os principais biomas brasileiros, as pressões sobre os ecossistemas nacionais (desmatamento, agropecuária, mineração), as políticas de conservação e o papel do Brasil nos debates internacionais sobre mudanças climáticas e biodiversidade. Acerca da questão ambiental no Brasil, julgue os itens a seguir. [O Brasil abriga seis grandes biomas — Amazônia, Cerrado, Mata Atlântica, Caatinga, Pantanal e Pampa — cada um com características ecológicas únicas, sendo que a Mata Atlântica é considerada um dos "hotspots" de biodiversidade mais ameaçados do planeta.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Geografia', 'Questão ambiental', 'Q21 Item 2 (TPS 2003): QUESTÃO 21 (TPS 2003) — Ecologia e questão ambiental no Brasil: questão sobre os principais biomas brasileiros, as pressões sobre os ecossistemas nacionais (desmatamento, agropecuária, mineração), as políticas de conservação e o papel do Brasil nos debates internacionais sobre mudanças climáticas e biodiversidade. Acerca da questão ambiental no Brasil, julgue os itens a seguir. [O desmatamento da Amazônia é fenômeno que se intensificou a partir dos anos 1970, associado à expansão da fronteira agrícola, à construção de estradas e projetos de colonização, ao garimpo e, mais recentemente, à expansão da soja e da pecuária.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Geografia', 'Questão ambiental', 'Q21 Item 3 (TPS 2003): QUESTÃO 21 (TPS 2003) — Ecologia e questão ambiental no Brasil: questão sobre os principais biomas brasileiros, as pressões sobre os ecossistemas nacionais (desmatamento, agropecuária, mineração), as políticas de conservação e o papel do Brasil nos debates internacionais sobre mudanças climáticas e biodiversidade. Acerca da questão ambiental no Brasil, julgue os itens a seguir. [O Cerrado brasileiro, segundo bioma mais extenso do país, é reconhecido como área de baixíssima biodiversidade e importância ecológica reduzida, tornando-o candidato natural para a expansão agrícola sem maiores impactos ambientais.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Geografia', 'Questão ambiental', 'Q21 Item 4 (TPS 2003): QUESTÃO 21 (TPS 2003) — Ecologia e questão ambiental no Brasil: questão sobre os principais biomas brasileiros, as pressões sobre os ecossistemas nacionais (desmatamento, agropecuária, mineração), as políticas de conservação e o papel do Brasil nos debates internacionais sobre mudanças climáticas e biodiversidade. Acerca da questão ambiental no Brasil, julgue os itens a seguir. [A política ambiental brasileira a partir dos anos 1980 incluiu a criação de unidades de conservação, o licenciamento ambiental de atividades potencialmente poluidoras e a promulgação da Política Nacional do Meio Ambiente, que estabeleceu o princípio do poluidor-pagador.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Geografia', 'Questão ambiental', 'Q21 Item 5 (TPS 2003): QUESTÃO 21 (TPS 2003) — Ecologia e questão ambiental no Brasil: questão sobre os principais biomas brasileiros, as pressões sobre os ecossistemas nacionais (desmatamento, agropecuária, mineração), as políticas de conservação e o papel do Brasil nos debates internacionais sobre mudanças climáticas e biodiversidade. Acerca da questão ambiental no Brasil, julgue os itens a seguir. [O Brasil assumiu compromissos voluntários de redução de desmatamento na Conferência de Copenhague de 2009, reconhecendo sua responsabilidade nas emissões globais de gases de efeito estufa associadas ao desmatamento.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Geografia', 'Rede urbana brasileira', 'Q22 Item 1 (TPS 2003): QUESTÃO 22 (TPS 2003) — Rede urbana brasileira: questão sobre a configuração da rede urbana do Brasil, a macrocefalia urbana, o papel das metrópoles, a hierarquia urbana, as metrópoles regionais, o processo de metropolização e os desafios da gestão das cidades brasileiras. Acerca da rede urbana brasileira, julgue os itens a seguir. [A rede urbana brasileira é marcada pela macrocefalia de São Paulo e Rio de Janeiro, que concentram parcela desproporcional da população, do PIB e das funções de gestão econômica e política do país, em detrimento de uma hierarquia urbana mais equilibrada.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Geografia', 'Rede urbana brasileira', 'Q22 Item 2 (TPS 2003): QUESTÃO 22 (TPS 2003) — Rede urbana brasileira: questão sobre a configuração da rede urbana do Brasil, a macrocefalia urbana, o papel das metrópoles, a hierarquia urbana, as metrópoles regionais, o processo de metropolização e os desafios da gestão das cidades brasileiras. Acerca da rede urbana brasileira, julgue os itens a seguir. [O processo de metropolização no Brasil, intensificado a partir dos anos 1960, resultou na formação de regiões metropolitanas caracterizadas por conurbação, interdependência funcional entre municípios e agudos problemas de mobilidade, habitação e saneamento.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Geografia', 'Rede urbana brasileira', 'Q22 Item 3 (TPS 2003): QUESTÃO 22 (TPS 2003) — Rede urbana brasileira: questão sobre a configuração da rede urbana do Brasil, a macrocefalia urbana, o papel das metrópoles, a hierarquia urbana, as metrópoles regionais, o processo de metropolização e os desafios da gestão das cidades brasileiras. Acerca da rede urbana brasileira, julgue os itens a seguir. [O interior do Brasil é caracterizado pela ausência de cidades médias com capacidade de polarização regional, sendo toda a hierarquia urbana centrada nas duas metrópoles nacionais, sem intermediários funcionais.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Geografia', 'Rede urbana brasileira', 'Q22 Item 4 (TPS 2003): QUESTÃO 22 (TPS 2003) — Rede urbana brasileira: questão sobre a configuração da rede urbana do Brasil, a macrocefalia urbana, o papel das metrópoles, a hierarquia urbana, as metrópoles regionais, o processo de metropolização e os desafios da gestão das cidades brasileiras. Acerca da rede urbana brasileira, julgue os itens a seguir. [A PNAD e o Censo Demográfico do IBGE registraram, a partir dos anos 1980, fenômeno de desmetropolização relativa, com crescimento mais acelerado de cidades médias e municípios do interior em relação às grandes regiões metropolitanas.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Geografia', 'Rede urbana brasileira', 'Q22 Item 5 (TPS 2003): QUESTÃO 22 (TPS 2003) — Rede urbana brasileira: questão sobre a configuração da rede urbana do Brasil, a macrocefalia urbana, o papel das metrópoles, a hierarquia urbana, as metrópoles regionais, o processo de metropolização e os desafios da gestão das cidades brasileiras. Acerca da rede urbana brasileira, julgue os itens a seguir. [As regiões metropolitanas brasileiras, criadas pela Lei Complementar nº 14/1973, foram estabelecidas para integrar o planejamento de serviços de interesse comum, mas enfrentam dificuldades de governança metropolitana por ausência de instância com autoridade e recursos adequados.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Direito', 'Direito Constitucional', 'Q23 Item 1 (TPS 2003): QUESTÃO 23 (TPS 2003) — Direito Constitucional brasileiro: questão sobre os princípios fundamentais da Constituição Federal de 1988, os direitos e garantias fundamentais, a organização dos poderes, o controle de constitucionalidade e as emendas constitucionais realizadas até 2003. Acerca do direito constitucional brasileiro, julgue os itens a seguir. [A Constituição Federal de 1988 consagra o princípio da dignidade da pessoa humana como fundamento da República, vinculando toda a ação estatal à sua promoção e proteção, inclusive nas relações entre particulares.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Direito', 'Direito Constitucional', 'Q23 Item 2 (TPS 2003): QUESTÃO 23 (TPS 2003) — Direito Constitucional brasileiro: questão sobre os princípios fundamentais da Constituição Federal de 1988, os direitos e garantias fundamentais, a organização dos poderes, o controle de constitucionalidade e as emendas constitucionais realizadas até 2003. Acerca do direito constitucional brasileiro, julgue os itens a seguir. [O mandado de injunção, previsto na Constituição de 1988, é instrumento processual destinado a suprir omissões legislativas que inviabilizam o exercício de direitos constitucionalmente assegurados, tendo sua eficácia debatida no Supremo Tribunal Federal.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Direito', 'Direito Constitucional', 'Q23 Item 3 (TPS 2003): QUESTÃO 23 (TPS 2003) — Direito Constitucional brasileiro: questão sobre os princípios fundamentais da Constituição Federal de 1988, os direitos e garantias fundamentais, a organização dos poderes, o controle de constitucionalidade e as emendas constitucionais realizadas até 2003. Acerca do direito constitucional brasileiro, julgue os itens a seguir. [Segundo a Constituição de 1988, as emendas constitucionais podem ser propostas exclusivamente pelo Presidente da República ou pela maioria absoluta dos membros de qualquer das Câmaras do Congresso Nacional.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Direito', 'Direito Constitucional', 'Q23 Item 4 (TPS 2003): QUESTÃO 23 (TPS 2003) — Direito Constitucional brasileiro: questão sobre os princípios fundamentais da Constituição Federal de 1988, os direitos e garantias fundamentais, a organização dos poderes, o controle de constitucionalidade e as emendas constitucionais realizadas até 2003. Acerca do direito constitucional brasileiro, julgue os itens a seguir. [O sistema brasileiro de controle de constitucionalidade combina o controle difuso, exercido por qualquer juiz em casos concretos, e o controle concentrado, realizado pelo STF em ações diretas de inconstitucionalidade, de constitucionalidade e de descumprimento de preceito fundamental.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Direito', 'Direito Constitucional', 'Q23 Item 5 (TPS 2003): QUESTÃO 23 (TPS 2003) — Direito Constitucional brasileiro: questão sobre os princípios fundamentais da Constituição Federal de 1988, os direitos e garantias fundamentais, a organização dos poderes, o controle de constitucionalidade e as emendas constitucionais realizadas até 2003. Acerca do direito constitucional brasileiro, julgue os itens a seguir. [A Constituição Federal veda expressamente a pena de morte no Brasil em qualquer hipótese, inclusive em caso de guerra declarada contra nação estrangeira, configurando cláusula pétrea insuscetível de reforma.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Direito', 'Direito Constitucional', 'Q24 Item 1 (TPS 2003): QUESTÃO 24 (TPS 2003) — Direito Administrativo e organização do Estado: questão sobre os princípios do direito administrativo (legalidade, impessoalidade, moralidade, publicidade, eficiência), a organização da administração pública federal, as agências reguladoras e o processo de reforma administrativa iniciado nos anos 1990. Julgue os itens a seguir, relativos ao direito administrativo e à organização do Estado brasileiro. [O princípio da legalidade na administração pública significa que o administrador público só pode agir quando e como a lei expressamente autorizar, distinguindo-se do princípio de legalidade aplicável aos particulares, que podem fazer tudo o que não for proibido por lei.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Direito', 'Direito Constitucional', 'Q24 Item 2 (TPS 2003): QUESTÃO 24 (TPS 2003) — Direito Administrativo e organização do Estado: questão sobre os princípios do direito administrativo (legalidade, impessoalidade, moralidade, publicidade, eficiência), a organização da administração pública federal, as agências reguladoras e o processo de reforma administrativa iniciado nos anos 1990. Julgue os itens a seguir, relativos ao direito administrativo e à organização do Estado brasileiro. [As agências reguladoras brasileiras, criadas a partir dos anos 1990 em consonância com a reforma do Estado, são caracterizadas por autonomia administrativa e financeira, mandatos fixos para seus dirigentes e independência técnica em relação ao poder político.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Direito', 'Direito Constitucional', 'Q24 Item 3 (TPS 2003): QUESTÃO 24 (TPS 2003) — Direito Administrativo e organização do Estado: questão sobre os princípios do direito administrativo (legalidade, impessoalidade, moralidade, publicidade, eficiência), a organização da administração pública federal, as agências reguladoras e o processo de reforma administrativa iniciado nos anos 1990. Julgue os itens a seguir, relativos ao direito administrativo e à organização do Estado brasileiro. [A emenda constitucional nº 19/1998, que introduziu o princípio da eficiência na administração pública, alterou substancialmente o regime jurídico dos servidores públicos, permitindo a demissão por insuficiência de desempenho após avaliação periódica.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Direito', 'Direito Constitucional', 'Q24 Item 4 (TPS 2003): QUESTÃO 24 (TPS 2003) — Direito Administrativo e organização do Estado: questão sobre os princípios do direito administrativo (legalidade, impessoalidade, moralidade, publicidade, eficiência), a organização da administração pública federal, as agências reguladoras e o processo de reforma administrativa iniciado nos anos 1990. Julgue os itens a seguir, relativos ao direito administrativo e à organização do Estado brasileiro. [O poder de polícia administrativa, exercido pela administração pública, consiste na faculdade de limitar o exercício de direitos individuais em benefício do interesse coletivo, sendo seu exercício condicionado pelos princípios da proporcionalidade e da legalidade.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Direito', 'Direito Constitucional', 'Q24 Item 5 (TPS 2003): QUESTÃO 24 (TPS 2003) — Direito Administrativo e organização do Estado: questão sobre os princípios do direito administrativo (legalidade, impessoalidade, moralidade, publicidade, eficiência), a organização da administração pública federal, as agências reguladoras e o processo de reforma administrativa iniciado nos anos 1990. Julgue os itens a seguir, relativos ao direito administrativo e à organização do Estado brasileiro. [A desconcentração administrativa distingue-se da descentralização pelo fato de que, na primeira, há transferência de atribuições dentro da mesma pessoa jurídica mediante criação de órgãos, enquanto na segunda há criação de novas pessoas jurídicas ou delegação a pessoas já existentes.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Direito', 'Direito Internacional Público', 'Q25 Item 1 (TPS 2003): QUESTÃO 25 (TPS 2003) — Direito Internacional Público (fontes e sujeitos): questão sobre as fontes do direito internacional, os sujeitos de direito internacional, a responsabilidade internacional dos Estados, os tratados internacionais e a relação entre direito internacional e direito interno. Com relação ao direito internacional público, julgue os itens a seguir. [As fontes do direito internacional, conforme o artigo 38 do Estatuto da Corte Internacional de Justiça, incluem os tratados internacionais, o costume internacional, os princípios gerais de direito reconhecidos pelas nações civilizadas, as decisões judiciais e a doutrina como meios auxiliares de determinação das normas.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Direito', 'Direito Internacional Público', 'Q25 Item 2 (TPS 2003): QUESTÃO 25 (TPS 2003) — Direito Internacional Público (fontes e sujeitos): questão sobre as fontes do direito internacional, os sujeitos de direito internacional, a responsabilidade internacional dos Estados, os tratados internacionais e a relação entre direito internacional e direito interno. Com relação ao direito internacional público, julgue os itens a seguir. [A personalidade jurídica internacional é atributo exclusivo dos Estados soberanos, não se estendendo às organizações internacionais, aos indivíduos ou a outros atores não estatais, segundo a doutrina clássica de direito internacional.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Direito', 'Direito Internacional Público', 'Q25 Item 3 (TPS 2003): QUESTÃO 25 (TPS 2003) — Direito Internacional Público (fontes e sujeitos): questão sobre as fontes do direito internacional, os sujeitos de direito internacional, a responsabilidade internacional dos Estados, os tratados internacionais e a relação entre direito internacional e direito interno. Com relação ao direito internacional público, julgue os itens a seguir. [O costume internacional, como fonte de direito internacional, exige a presença de dois elementos: a prática geral e uniforme dos Estados (elemento material) e a convicção de que tal prática é juridicamente obrigatória (opinio juris).]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Direito', 'Direito Internacional Público', 'Q25 Item 4 (TPS 2003): QUESTÃO 25 (TPS 2003) — Direito Internacional Público (fontes e sujeitos): questão sobre as fontes do direito internacional, os sujeitos de direito internacional, a responsabilidade internacional dos Estados, os tratados internacionais e a relação entre direito internacional e direito interno. Com relação ao direito internacional público, julgue os itens a seguir. [A responsabilidade internacional do Estado surge quando um ato internacionalmente ilícito é atribuído ao Estado e viola uma obrigação internacional, obrigando-o à cessação do ato, ao oferecimento de garantias de não repetição e à reparação do dano causado.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Direito', 'Direito Internacional Público', 'Q25 Item 5 (TPS 2003): QUESTÃO 25 (TPS 2003) — Direito Internacional Público (fontes e sujeitos): questão sobre as fontes do direito internacional, os sujeitos de direito internacional, a responsabilidade internacional dos Estados, os tratados internacionais e a relação entre direito internacional e direito interno. Com relação ao direito internacional público, julgue os itens a seguir. [O princípio do pacta sunt servanda, fundamento do direito dos tratados, estabelece que os tratados em vigor vinculam as partes e devem ser cumpridos de boa-fé, não podendo um Estado invocar disposições de seu direito interno para justificar o descumprimento de obrigação internacional.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Direito', 'Direito Internacional Público', 'Q26 Item 1 (TPS 2003): QUESTÃO 26 (TPS 2003) — Direito Internacional Público (ONU e segurança coletiva): questão sobre a Carta da ONU, o sistema de segurança coletiva, o papel do Conselho de Segurança, o uso da força no direito internacional, a proibição da ameaça ou uso da força e as exceções previstas (legítima defesa, autorização do CSNU). Acerca do sistema de segurança coletiva da ONU e do uso da força no direito internacional, julgue os itens a seguir. [A Carta da ONU proíbe em termos absolutos a ameaça ou o uso da força nas relações internacionais, sem admitir qualquer exceção, tendo revogado o direito consuetudinário de legítima defesa dos Estados.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Direito', 'Direito Internacional Público', 'Q26 Item 2 (TPS 2003): QUESTÃO 26 (TPS 2003) — Direito Internacional Público (ONU e segurança coletiva): questão sobre a Carta da ONU, o sistema de segurança coletiva, o papel do Conselho de Segurança, o uso da força no direito internacional, a proibição da ameaça ou uso da força e as exceções previstas (legítima defesa, autorização do CSNU). Acerca do sistema de segurança coletiva da ONU e do uso da força no direito internacional, julgue os itens a seguir. [O Conselho de Segurança da ONU é o órgão responsável pela manutenção da paz e da segurança internacionais, podendo adotar medidas coercitivas vinculantes, incluindo o uso da força armada, quando constatar ameaça à paz, ruptura da paz ou ato de agressão.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Direito', 'Direito Internacional Público', 'Q26 Item 3 (TPS 2003): QUESTÃO 26 (TPS 2003) — Direito Internacional Público (ONU e segurança coletiva): questão sobre a Carta da ONU, o sistema de segurança coletiva, o papel do Conselho de Segurança, o uso da força no direito internacional, a proibição da ameaça ou uso da força e as exceções previstas (legítima defesa, autorização do CSNU). Acerca do sistema de segurança coletiva da ONU e do uso da força no direito internacional, julgue os itens a seguir. [O direito de legítima defesa previsto no artigo 51 da Carta da ONU é restrito à resposta a um ataque armado já ocorrido, não abrangendo a chamada legítima defesa preemptiva ou preventiva, que não possui fundamento na Carta.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Direito', 'Direito Internacional Público', 'Q26 Item 4 (TPS 2003): QUESTÃO 26 (TPS 2003) — Direito Internacional Público (ONU e segurança coletiva): questão sobre a Carta da ONU, o sistema de segurança coletiva, o papel do Conselho de Segurança, o uso da força no direito internacional, a proibição da ameaça ou uso da força e as exceções previstas (legítima defesa, autorização do CSNU). Acerca do sistema de segurança coletiva da ONU e do uso da força no direito internacional, julgue os itens a seguir. [As operações de manutenção da paz da ONU, não previstas explicitamente na Carta, foram desenvolvidas na prática como mecanismo intermediário entre as medidas do capítulo VI (solução pacífica de controvérsias) e as do capítulo VII (ação coercitiva), baseando-se no consentimento dos Estados anfitriões.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Direito', 'Direito Internacional Público', 'Q26 Item 5 (TPS 2003): QUESTÃO 26 (TPS 2003) — Direito Internacional Público (ONU e segurança coletiva): questão sobre a Carta da ONU, o sistema de segurança coletiva, o papel do Conselho de Segurança, o uso da força no direito internacional, a proibição da ameaça ou uso da força e as exceções previstas (legítima defesa, autorização do CSNU). Acerca do sistema de segurança coletiva da ONU e do uso da força no direito internacional, julgue os itens a seguir. [A intervenção humanitária unilateral — uso da força por um Estado ou grupo de Estados sem autorização do Conselho de Segurança para proteger populações civis — é amplamente aceita como exceção legítima à proibição do uso da força no direito internacional contemporâneo.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Economia', 'Microeconomia', 'Q27 Item 1 (TPS 2003): QUESTÃO 27 (TPS 2003) — Conceitos básicos de microeconomia: questão sobre os fundamentos da análise microeconômica, incluindo teoria do consumidor, teoria da firma, estruturas de mercado (concorrência perfeita, oligopólio, monopólio), falhas de mercado e externalidades. Acerca dos conceitos básicos de microeconomia, julgue os itens a seguir. [Em concorrência perfeita, no equilíbrio de longo prazo, o preço iguala-se ao custo marginal e ao custo médio mínimo, de modo que as firmas obtêm apenas lucro normal (zero econômico), sem incentivo para entrada ou saída de empresas no mercado.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Economia', 'Microeconomia', 'Q27 Item 2 (TPS 2003): QUESTÃO 27 (TPS 2003) — Conceitos básicos de microeconomia: questão sobre os fundamentos da análise microeconômica, incluindo teoria do consumidor, teoria da firma, estruturas de mercado (concorrência perfeita, oligopólio, monopólio), falhas de mercado e externalidades. Acerca dos conceitos básicos de microeconomia, julgue os itens a seguir. [O monopólio natural surge quando os custos fixos são elevados e os custos marginais de produção são decrescentes, tornando socialmente eficiente que apenas uma firma atenda ao mercado, o que justifica sua regulação pelo Estado.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Economia', 'Microeconomia', 'Q27 Item 3 (TPS 2003): QUESTÃO 27 (TPS 2003) — Conceitos básicos de microeconomia: questão sobre os fundamentos da análise microeconômica, incluindo teoria do consumidor, teoria da firma, estruturas de mercado (concorrência perfeita, oligopólio, monopólio), falhas de mercado e externalidades. Acerca dos conceitos básicos de microeconomia, julgue os itens a seguir. [As externalidades negativas, como a poluição industrial, levam à subprodução em relação ao nível socialmente ótimo, pois os produtores não internalizam os custos externos gerados a terceiros, justificando intervenção governamental via taxação ou regulação.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Economia', 'Microeconomia', 'Q27 Item 4 (TPS 2003): QUESTÃO 27 (TPS 2003) — Conceitos básicos de microeconomia: questão sobre os fundamentos da análise microeconômica, incluindo teoria do consumidor, teoria da firma, estruturas de mercado (concorrência perfeita, oligopólio, monopólio), falhas de mercado e externalidades. Acerca dos conceitos básicos de microeconomia, julgue os itens a seguir. [A elasticidade-preço da demanda mede a sensibilidade da quantidade demandada a variações no preço do bem, sendo que bens com demanda inelástica (elasticidade < 1) têm sua receita total aumentada quando o preço sobe.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Economia', 'Microeconomia', 'Q27 Item 5 (TPS 2003): QUESTÃO 27 (TPS 2003) — Conceitos básicos de microeconomia: questão sobre os fundamentos da análise microeconômica, incluindo teoria do consumidor, teoria da firma, estruturas de mercado (concorrência perfeita, oligopólio, monopólio), falhas de mercado e externalidades. Acerca dos conceitos básicos de microeconomia, julgue os itens a seguir. [Em estruturas de oligopólio, o modelo de Cournot prevê que as firmas maximizam seus lucros decidindo simultaneamente sobre as quantidades a produzir, considerando a produção das rivais como dada, resultando em equilíbrio com quantidade menor e preço maior do que em concorrência perfeita.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Economia', 'Macroeconomia', 'Q28 Item 1 (TPS 2003): QUESTÃO 28 (TPS 2003) — Macroeconomia: questão sobre os conceitos e modelos macroeconômicos, incluindo o modelo IS-LM, a teoria quantitativa da moeda, as políticas fiscal e monetária, o multiplicador keynesiano, a curva de Phillips e os debates entre keynesianos e monetaristas. Com relação à macroeconomia, julgue os itens a seguir. [No modelo keynesiano simples, o multiplicador fiscal indica que um aumento nos gastos do governo gera um aumento no produto nacional mais do que proporcional, desde que haja capacidade ociosa na economia e que as famílias tenham propensão marginal a consumir positiva.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Economia', 'Macroeconomia', 'Q28 Item 2 (TPS 2003): QUESTÃO 28 (TPS 2003) — Macroeconomia: questão sobre os conceitos e modelos macroeconômicos, incluindo o modelo IS-LM, a teoria quantitativa da moeda, as políticas fiscal e monetária, o multiplicador keynesiano, a curva de Phillips e os debates entre keynesianos e monetaristas. Com relação à macroeconomia, julgue os itens a seguir. [A teoria quantitativa da moeda, expressa pela equação de trocas (MV=PQ), implica que, mantidos constantes a velocidade de circulação e o produto real, um aumento na oferta monetária resultará em aumento proporcional no nível geral de preços.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Economia', 'Macroeconomia', 'Q28 Item 3 (TPS 2003): QUESTÃO 28 (TPS 2003) — Macroeconomia: questão sobre os conceitos e modelos macroeconômicos, incluindo o modelo IS-LM, a teoria quantitativa da moeda, as políticas fiscal e monetária, o multiplicador keynesiano, a curva de Phillips e os debates entre keynesianos e monetaristas. Com relação à macroeconomia, julgue os itens a seguir. [A curva de Phillips original, que relaciona taxa de desemprego e taxa de inflação, foi questionada pelos monetaristas, que introduziram o conceito de taxa natural de desemprego e argumentaram que a curva é vertical no longo prazo.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Economia', 'Macroeconomia', 'Q28 Item 4 (TPS 2003): QUESTÃO 28 (TPS 2003) — Macroeconomia: questão sobre os conceitos e modelos macroeconômicos, incluindo o modelo IS-LM, a teoria quantitativa da moeda, as políticas fiscal e monetária, o multiplicador keynesiano, a curva de Phillips e os debates entre keynesianos e monetaristas. Com relação à macroeconomia, julgue os itens a seguir. [A política monetária expansionista, realizada pelo Banco Central mediante redução da taxa de juros ou aumento da base monetária, tende a estimular o investimento, aumentar a demanda agregada e elevar o produto no curto prazo.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Economia', 'Macroeconomia', 'Q28 Item 5 (TPS 2003): QUESTÃO 28 (TPS 2003) — Macroeconomia: questão sobre os conceitos e modelos macroeconômicos, incluindo o modelo IS-LM, a teoria quantitativa da moeda, as políticas fiscal e monetária, o multiplicador keynesiano, a curva de Phillips e os debates entre keynesianos e monetaristas. Com relação à macroeconomia, julgue os itens a seguir. [O modelo IS-LM, desenvolvido por Hicks e Hansen como interpretação do pensamento keynesiano, representa o equilíbrio simultâneo no mercado de bens e serviços (curva IS) e no mercado monetário (curva LM), determinando a taxa de juros e o produto de equilíbrio.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Economia', 'Comércio Internacional', 'Q29 Item 1 (TPS 2003): QUESTÃO 29 (TPS 2003) — Comércio internacional: questão sobre as teorias do comércio internacional (vantagens comparativas, vantagens absolutas, modelo Heckscher-Ohlin), as políticas comerciais (tarifas, cotas, dumping, subsídios), o sistema multilateral de comércio e a OMC. Julgue os itens a seguir, referentes ao comércio internacional. [A teoria das vantagens comparativas de Ricardo demonstra que o comércio internacional é mutuamente benéfico mesmo quando um país tem vantagem absoluta na produção de todos os bens, pois a especialização segundo os custos relativos permite ganhos de bem-estar para ambos os países.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Economia', 'Comércio Internacional', 'Q29 Item 2 (TPS 2003): QUESTÃO 29 (TPS 2003) — Comércio internacional: questão sobre as teorias do comércio internacional (vantagens comparativas, vantagens absolutas, modelo Heckscher-Ohlin), as políticas comerciais (tarifas, cotas, dumping, subsídios), o sistema multilateral de comércio e a OMC. Julgue os itens a seguir, referentes ao comércio internacional. [O modelo Heckscher-Ohlin prevê que os países exportarão bens que usam intensivamente o fator de produção de que são relativamente mais dotados, sendo que o comércio tende a equalizar os preços dos fatores entre países com estruturas produtivas diferentes.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Economia', 'Comércio Internacional', 'Q29 Item 3 (TPS 2003): QUESTÃO 29 (TPS 2003) — Comércio internacional: questão sobre as teorias do comércio internacional (vantagens comparativas, vantagens absolutas, modelo Heckscher-Ohlin), as políticas comerciais (tarifas, cotas, dumping, subsídios), o sistema multilateral de comércio e a OMC. Julgue os itens a seguir, referentes ao comércio internacional. [As cotas de importação e as tarifas alfandegárias têm efeitos econômicos equivalentes sobre o preço interno e a quantidade importada, distinguindo-se apenas pelo destino da renda transferida: nos direitos alfandegários, para o governo; nas cotas, potencialmente para os importadores com licença.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Economia', 'Comércio Internacional', 'Q29 Item 4 (TPS 2003): QUESTÃO 29 (TPS 2003) — Comércio internacional: questão sobre as teorias do comércio internacional (vantagens comparativas, vantagens absolutas, modelo Heckscher-Ohlin), as políticas comerciais (tarifas, cotas, dumping, subsídios), o sistema multilateral de comércio e a OMC. Julgue os itens a seguir, referentes ao comércio internacional. [O dumping, definido pela OMC como exportação de produto a preço inferior ao seu valor normal no mercado doméstico do exportador, é prática proibida pelo direito internacional econômico e sujeita a medidas antidumping pelos países importadores prejudicados.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Economia', 'Comércio Internacional', 'Q29 Item 5 (TPS 2003): QUESTÃO 29 (TPS 2003) — Comércio internacional: questão sobre as teorias do comércio internacional (vantagens comparativas, vantagens absolutas, modelo Heckscher-Ohlin), as políticas comerciais (tarifas, cotas, dumping, subsídios), o sistema multilateral de comércio e a OMC. Julgue os itens a seguir, referentes ao comércio internacional. [O sistema multilateral de comércio, consolidado com a criação da OMC em 1995, baseia-se nos princípios da nação mais favorecida, do tratamento nacional e da reciprocidade, prevendo mecanismo de solução de controvérsias com capacidade de autorizar retaliações.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Economia', 'Economia Brasileira', 'Q30 Item 1 (TPS 2003): QUESTÃO 30 (TPS 2003) — Economia brasileira: questão sobre a trajetória da economia brasileira, abordando o Plano Real e a estabilização monetária de 1994, o regime de câmbio fixo e sua crise em 1999, a adoção do tripé macroeconômico (câmbio flutuante, metas de inflação e superávit primário) e os desafios do desenvolvimento econômico. Acerca da economia brasileira, julgue os itens a seguir. [O Plano Real, implementado em 1994, combinou âncora cambial, abertura comercial e política monetária restritiva para estabilizar a inflação, sendo precedido por um processo de desindexação da economia mediante a Unidade Real de Valor (URV).]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Economia', 'Economia Brasileira', 'Q30 Item 2 (TPS 2003): QUESTÃO 30 (TPS 2003) — Economia brasileira: questão sobre a trajetória da economia brasileira, abordando o Plano Real e a estabilização monetária de 1994, o regime de câmbio fixo e sua crise em 1999, a adoção do tripé macroeconômico (câmbio flutuante, metas de inflação e superávit primário) e os desafios do desenvolvimento econômico. Acerca da economia brasileira, julgue os itens a seguir. [A crise cambial de janeiro de 1999, que forçou o Brasil a abandonar o regime de câmbio fixo adotado desde o Plano Real, resultou em intensa recessão com queda do PIB superior a 5% e disparada da inflação acima de 20% ao ano.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Economia', 'Economia Brasileira', 'Q30 Item 3 (TPS 2003): QUESTÃO 30 (TPS 2003) — Economia brasileira: questão sobre a trajetória da economia brasileira, abordando o Plano Real e a estabilização monetária de 1994, o regime de câmbio fixo e sua crise em 1999, a adoção do tripé macroeconômico (câmbio flutuante, metas de inflação e superávit primário) e os desafios do desenvolvimento econômico. Acerca da economia brasileira, julgue os itens a seguir. [O tripé macroeconômico adotado pelo Brasil a partir de 1999 — câmbio flutuante, regime de metas de inflação e geração de superávits primários — visava conferir credibilidade à política econômica e garantir a sustentabilidade da dívida pública.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2003, 'Economia', 'Economia Brasileira', 'Q30 Item 4 (TPS 2003): QUESTÃO 30 (TPS 2003) — Economia brasileira: questão sobre a trajetória da economia brasileira, abordando o Plano Real e a estabilização monetária de 1994, o regime de câmbio fixo e sua crise em 1999, a adoção do tripé macroeconômico (câmbio flutuante, metas de inflação e superávit primário) e os desafios do desenvolvimento econômico. Acerca da economia brasileira, julgue os itens a seguir. [A taxa de câmbio sobrevalorizada durante o período de câmbio fixo do Plano Real (1994-1999) contribuiu para o crescimento das importações e o surgimento de déficits em conta corrente, financiados por influxos de capital externo que tornaram o país vulnerável a crises de balanço de pagamentos.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2003, 'Economia', 'Economia Brasileira', 'Q30 Item 5 (TPS 2003): QUESTÃO 30 (TPS 2003) — Economia brasileira: questão sobre a trajetória da economia brasileira, abordando o Plano Real e a estabilização monetária de 1994, o regime de câmbio fixo e sua crise em 1999, a adoção do tripé macroeconômico (câmbio flutuante, metas de inflação e superávit primário) e os desafios do desenvolvimento econômico. Acerca da economia brasileira, julgue os itens a seguir. [O sistema de metas de inflação adotado pelo Brasil em 1999 delega ao Banco Central a responsabilidade de manter a inflação dentro de intervalos previamente estabelecidos pelo Conselho Monetário Nacional, utilizando a taxa Selic como principal instrumento de política monetária.]', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL);-- TPS 2004 — 149 itens
INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2004, 'Português', 'Macroeconomia', 'Item 1 (TPS 2004): Cargo: Terceiro Secretário da Carreira de Diplomata LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. | Ao receber este caderno, confira se ele contém canto e cinquenta Itens corretamente ordenados de 1 a 150. 2. Caso academin esteja incompleto eu tenha qualquer de niln, salicite ac fiscal de sala mais próximc que forme as providéiasives. pontuação negative, conforme consta no Edital do 20 de jano ro de 2004. 4\. Nau ilice enhurmelerial de consula que não seja lumecidu pek: CCSPC. nu decurrer da pruva wau preenchimento da loma de resposta. prova. folha ce respostas pocerà implicera anulação de sus prova. AGENDA 1 21/3/2004 Dvugação a part das 10h. das gabuarils of cinis pro in mars da prova abjetiva, ni InTIC rin encerpe elstrórico htt://www.ceape.unb.br-arce qusorcs de aviace do CESIEU 18-en Braai a locale no "crário que serao informados na divulgação desses pacaritos. || 27 28/3/2004-Reali', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 2 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | A relação lógica entre os dois primeiros parágrafos pode assim ser descrita: no segundo parágrafo, enuncia-se a idéia da existência de forças geradoras que, como apontam pensadores de outras épocas, foram responsáveis pelas mudanças cíclicas, elencadas no primeiro parágrafo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 3 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | Os dados e os argumentos apresentados pelo autor asseguram a objetividade do discurso, incisivo e científico. No entanto, para se eliminarem os traços de subjetividade, seriam necessárias as seguintes alterações: retirada de “ parece que” (R.3) e troca de “ parecem ajustar-se” (R.10) por ajustam-se.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 4 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | As “ transições” apontadas por Toynbee organizam-se diacronicamente de tal forma que são excludentes, e efetivamente ocorreram na ordem em que foram apresentadas. UnB / CESPE – IRBr – Primeira Fase – Aplicação: 20/3/2004 Teste de Pré-Seleção É permitida a reprodução apenas para fins didáticos, desde que citada a fonte. Cargo: Terceiro Secretário da Carreira de Diplomata – 1 –', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 5 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | A regra de acentuação gráfica ilustrada em “ pólos” (R.6) não diz respeito à terminação da palavra, o que também ocorre com os vocábulos pôr (verbo) e ás (substantivo).', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 6 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | Na linha 6, observa-se que a palavra “ ordem” não recebeu acento gráfico, assim como seu plural também não o receberia. Isso ocorre porque as palavras paroxítonas terminadas em -em/-ens não se acentuam, regra da qual a palavra hífens é exceção.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 7 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | As reescrituras de “a que chamou” (R.7-8) e de “de que dispomos” (R.13) como, respectivamente, que chamou de e que dispomos estão ambas de acordo com a modalidade escrita padrão da língua portuguesa e preservam o sentido original do texto.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 8 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | Na linha 9, a ligação estabelecida entre os adjetivos “notáveis” e “hipotéticos” manter-se-ia coerente com o texto, assim como seria mantida a correção gramatical da frase, caso se substituísse “mesmo que” por em bora ou posto que.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 9 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | No período “Tem sido extremamente difícil entender o poder do patriarcado, por ser ele totalmente preponderante” (R.14), não se contrariaria o sentido original do texto, se a expressão grifada fosse substituída por hegemônico.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 10 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | Na linha 16, o pronome “que” exerce a mesma função sintática do termo que o antecede: predicativo do sujeito.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 11 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | Os pronomes relativos “que” (R.16) e “cujas” (R.17) têm como elemento antecedente a mesma expressão nominal.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 12 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | O pronome “tais” (R.18), sem referência própria, tem seu sentido atribuído pelo termo antecedente “universalmente aceitas” (R.17).', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 13 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | A oração “que terá profundo impacto sobre nossa vida” (R.21) poderia estar entre parênteses ou entre travessões, mas não sem as vírgulas, porque, neste caso, assumiria um caráter explicativo, o que acarretaria incoerência textual.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 14 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | Os vocábulos “dos” e “da” (R.27) provêm ambos da contração da preposição de com outro vocábulo: em “ dos”, com um pronome demonstrativo e, em “ da”, com um artigo definido.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 15 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | Mantêm-se a correção gramatical e o sentido original do texto, se o último parágrafo for reescrito do seguinte modo: Nessa ampla perspectiva de evolução cultural, cuja mudança do atual paradigma, percebe-se um processo mais vasto, com uma flutuação notavelmente regular de sistemas de valores, que pode ser apontado ao longo de toda a civilização ocidental e da maioria das outras culturas. Texto II – itens de 16 a 20 e 29-30 Além de serem interdependentes, identidade e 1 diferença partilham uma importante característica: elas são o resultado de atos de criação lingüística.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 16 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | Comprometer-se-ia o sentido original do período situado entre as linhas 3 e 6, caso se substituísse a construção na voz passiva analítica “à espera de serem reveladas ou descobertas, respeitadas ou toleradas” (R.5-6) pela passiva pronominal correspondente.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 17 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | Atendendo-se às prescrições gramaticais, o segmento “ Somos nós que as fabricamos” (R.8) poderia ser substituído por Somos nós quem as fabrica.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 18 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | Ao final do 3.o parágrafo, mantendo-se a coerência e a coesão textuais, poderia ser acrescentado o seguinte trecho: Em outras palavras, é a própria dicotomia um dos meios pelos quais o significado é fixado.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 19 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | No texto, afirma-se que os grupos sociais que estão assimetricamente situados são os que lutam para garantir o acesso aos privilégios, como evidencia o emprego das vírgulas na linha 28.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'Português', 'Interpretação de texto', 'Item 20 (TPS 2004): Para entender a atual e multifacetada crise cultural, precisamos adotar uma perspectiva extremamente ampla e analisar a 1 situação no contexto da evolução cultural humana. Os historiadores estão longe de elaborarem uma teoria abrangente da dinâmica cultural, mas parece que todas as civilizações passam por processos cíclicos semelhantes de gênese, crescimento, colapso e desintegração. Segundo os an | De acordo com o texto, identidade e diferença devem ser compreendidas em sua dimensão simbólica, de representação, e analisadas com base nas relações de poder. UnB / CESPE – IRBr – Primeira Fase – Aplicação: 20/3/2004 Teste de Pré-Seleção É permitida a reprodução apenas para fins didáticos, desde que citada a fonte. Cargo: Terceiro Secretário da Carreira de Diplomata – 2 – Texto III – itens de 21 a 30 1 A ética contemporânea faz grande alvoroço em torno das diferenças culturais. Sua concepção do outro tem em vista essencialmente esse tipo de diferenças. E seu grande idea', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'História do Brasil', 'História do Brasil', 'Item 21 (TPS 2004): historiador) da ética contemporânea é o culturalismo, a fascinação verdadeiramente turística pela multiplicidade dos hábitos, dos costumes, das crenças. E especialmente pela inevitável bizarria das formações imaginárias (religiões, representações sexuais, formas de encarnação da autoridade...). Sim, o essencial da “objetividade” ética provém de uma sociologia vulgar, diretamente herdada do espanto | A articulação das idéias do texto não permite a inferência de que, no passado, as diferenças culturais eram relegadas pela ética e, no momento, são alardeadas em razão dos freqüentes processos de exclusão social.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'História do Brasil', 'História do Brasil', 'Item 22 (TPS 2004): historiador) da ética contemporânea é o culturalismo, a fascinação verdadeiramente turística pela multiplicidade dos hábitos, dos costumes, das crenças. E especialmente pela inevitável bizarria das formações imaginárias (religiões, representações sexuais, formas de encarnação da autoridade...). Sim, o essencial da “objetividade” ética provém de uma sociologia vulgar, diretamente herdada do espanto | Segundo o autor do texto, os guardiães da ética contemporânea explicam toda forma de exclusão com base no determinismo cultural porque idealizam a convivência pacífica entre os povos.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'História do Brasil', 'História do Brasil', 'Item 23 (TPS 2004): historiador) da ética contemporânea é o culturalismo, a fascinação verdadeiramente turística pela multiplicidade dos hábitos, dos costumes, das crenças. E especialmente pela inevitável bizarria das formações imaginárias (religiões, representações sexuais, formas de encarnação da autoridade...). Sim, o essencial da “objetividade” ética provém de uma sociologia vulgar, diretamente herdada do espanto | No último parágrafo, o autor sustenta que as diferenças, mais do que ilusórias, são falseadas pela crença de uma verdade estável, resultante do raciocínio silogístico frágil por meio do qual a corrente culturalista concebe a alteridade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2004, 'História do Brasil', 'História do Brasil', 'Item 24 (TPS 2004): historiador) da ética contemporânea é o culturalismo, a fascinação verdadeiramente turística pela multiplicidade dos hábitos, dos costumes, das crenças. E especialmente pela inevitável bizarria das formações imaginárias (religiões, representações sexuais, formas de encarnação da autoridade...). Sim, o essencial da “objetividade” ética provém de uma sociologia vulgar, diretamente herdada do espanto | O texto é composto essencialmente por enunciados categóricos, como evidencia o emprego reiterado de formas verbais no presente do indicativo.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2004, 'História do Brasil', 'História do Brasil', 'Item 25 (TPS 2004): historiador) da ética contemporânea é o culturalismo, a fascinação verdadeiramente turística pela multiplicidade dos hábitos, dos costumes, das crenças. E especialmente pela inevitável bizarria das formações imaginárias (religiões, representações sexuais, formas de encarnação da autoridade...). Sim, o essencial da “objetividade” ética provém de uma sociologia vulgar, diretamente herdada do espanto | O texto informa que a concepção culturalista, cujos fundamentos advêm da sociologia vulgar, postula que o “outro” corresponde ao segmento selvagem, que estará sempre presente como o outro ameaçador, o bárbaro. Assim, para essa corrente, a ética prevalente é ainda a do branco colonizador. 26 O trecho “a fascinação (...) imaginárias” (R.12-15) suscita duas observações: há, nele, indicadores da subjetividade do autor — “ fascinação verdadeiramente turística” e “ inevitável bizarria” —; a inserção da vírgula após “ crenças” (R.14), no lugar do ponto, seguida de alteração da ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
