INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2007, 'Português', 'Interpretação de texto', 'Item 1 (TPS 2007): Ministério das Relações Exteriores Admissão à Carreira de Diplomata Teste de Pré-Seleção (TPS) (Primeira Etapa) LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. | Ao receber este caderno, confira atentamente se o tipo de caderno - PAPA - coincide com o que está registrado na sua folha de respostas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2007, 'Português', 'Interpretação de texto', 'Item 2 (TPS 2007): Ministério das Relações Exteriores Admissão à Carreira de Diplomata Teste de Pré-Seleção (TPS) (Primeira Etapa) LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. | Este caderno contém o Teste de Pré-Seleção (TPS)-Primeira Etapa-com trinta questões, corretamente ordenadas de 1 a 30. 3 A folha de rascunho inserida na contracapa deste caderno poderá ser utilizada para auxiliá-lo na marcação de suas respostas às questões desse teste, não valendo, contudo, para correção do seu teste. item ERRADO. 6 7 8', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2007, 'Política Internacional', NULL, 'Item 3 (TPS 2007) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2007, 'Política Internacional', NULL, 'Item 4 (TPS 2007) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2007, 'Política Internacional', NULL, 'Item 5 (TPS 2007) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2007, 'Política Internacional', NULL, 'Item 6 (TPS 2007) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2007, 'Política Internacional', NULL, 'Item 7 (TPS 2007) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2007, 'Política Internacional', NULL, 'Item 8 (TPS 2007) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2007, 'Português', 'Interpretação de texto', 'Item 9 (TPS 2007): Ministério das Relações Exteriores Admissão à Carreira de Diplomata Teste de Pré-Seleção (TPS) (Primeira Etapa) LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Recomenda-se não marcar ao acaso: em cada questão do tipo múltipla escolha e em cada item do tipo CERTO ou ERRADO, se a resposta divergir do gabarito oficial definitivo, o candidato receberá pontuação negativa, conforme consta em edital. Não utilize | Aduração da primeira etapa do TPS é de três horas, já incluido o tempo destinado à identificação-que será feita no decorrer da aplicação - e ao preenchimento da folha de respostas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2007, 'Português', 'Interpretação de texto', 'Item 10 (TPS 2007): Ministério das Relações Exteriores Admissão à Carreira de Diplomata Teste de Pré-Seleção (TPS) (Primeira Etapa) LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Recomenda-se não marcar ao acaso: em cada questão do tipo múltipla escolha e em cada item do tipo CERTO ou ERRADO, se a resposta divergir do gabarito oficial definitivo, o candidato receberá pontuação negativa, conforme consta em edital. Não utilize | Você deverá permanecer obrigatoriamente em sala por, no mínimo, uma hora após o início do teste e poderá levar este caderno somente no decurso dos últimos quinze minutos anteriores ao horário determinado para o término do teste.', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2007, 'Português', 'Macroeconomia', 'Item 11 (TPS 2007): Ministério das Relações Exteriores Admissão à Carreira de Diplomata Teste de Pré-Seleção (TPS) (Primeira Etapa) LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Recomenda-se não marcar ao acaso: em cada questão do tipo múltipla escolha e em cada item do tipo CERTO ou ERRADO, se a resposta divergir do gabarito oficial definitivo, o candidato receberá pontuação negativa, conforme consta em edital. Não utilize | Ao terminar a primeira etapa do TPS, chame o fiscal de sala mais próximo, devolva-lhe a sua folha de respostas e deixe o local do teste.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2007, 'Português', 'Interpretação de texto', 'Item 12 (TPS 2007): Ministério das Relações Exteriores Admissão à Carreira de Diplomata Teste de Pré-Seleção (TPS) (Primeira Etapa) LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. Recomenda-se não marcar ao acaso: em cada questão do tipo múltipla escolha e em cada item do tipo CERTO ou ERRADO, se a resposta divergir do gabarito oficial definitivo, o candidato receberá pontuação negativa, conforme consta em edital. Não utilize | A desobediência a qualquer uma das determinações constantes no presente caderno ou na folha de respostas poderá implicar a anulação de seu teste. AGENDA (DATAS PROVÁVEIS)', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
