INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2008, 'Português', 'Macroeconomia', 'Item 1 (TPS 2008): Admissão à Carreira de Diplomata LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. | Ao receber este caderno, confira atentamente se o tipo de caderno-Caderno SUL-coincide com o que está registrado em sua folha de respostas e no rodapé de cada página numerada deste caderno. Em seguida, verifique se ele contém trinta e uma questões, correspondentes à segunda etapa da prova objetiva, corretamente ordenadas de 35 a 65. 2 Caso o caderno esteja incompleto ou tenha qualquer defeito, solicite ao fiscal de sala mais próximo que tome as providências cabíveis, pois não serão aceitas reclamações posteriores. 4 5 6 7', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2008, 'Política Internacional', NULL, 'Item 2 (TPS 2008) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
