INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2010, 'Português', 'Interpretação de texto', 'Item 1 (TPS 2010): Admissão à Carreira de Diplomata LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. | Ao receber este caderno, confira atentamente se o tipo de caderno - Caderno C-coincide com o que está registrado em sua folha de respostas e no rodapé de cada página numerada deste caderno. Em seguida, verifique se ele contém quarenta e uma questões, correspondentes à segunda etapa da prova objetiva, corretamente ordenadas de 40 a 80. 2 Quando autorizado pelo chefe de sala, no momento da identificação, escreva, no espaço apropriado da folha de respostas, com a sua caligrafia usual, a seguinte frase: Entre as dificuldades se esconde a oportunidade.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2010, 'Política Internacional', NULL, 'Item 2 (TPS 2010) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2010, 'Política Internacional', NULL, 'Item 3 (TPS 2010) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2010, 'Política Internacional', NULL, 'Item 4 (TPS 2010) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
  ('exam', 2010, 'Português', 'Macroeconomia', 'Item 5 (TPS 2010): Admissão à Carreira de Diplomata LEIA COM ATENÇÃO AS INSTRUÇÕES ABAIXO. | Você encontrará dois tipos de questões objetivas: múltipla escolha e CERTO ou ERRADO. Nas questões do tipo múltipla escolha, marque, em cada uma, a única opção correta (A, B, C, Dou E), de acordo com o respectivo comando. Nas questões do tipo CERTO ou ERRADO, que têm quatro itens cada, marque, para cada item: o campo designado com o código C, caso julgue o item CERTO, ou o campo designado com o código E, caso julgue o item ERRADO. 6 Recomenda-se não marcar ao acaso: em cada questão do tipo múltipla escolha e em cada item do tipo CERTO ou ERRADO, se a resposta divergir do gabarito oficial definitivo, o candidato receberá pontuação negativa, conforme consta em edital. fornecido pelo CESPE/UNB. de um fiscal de sala. respostas e deixe o local de prova. folha de respostas poderá implicar a anul', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
