INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2015, 'Português', 'Interpretação de texto', 'Item 1 (TPS 2015): ||154IRBRDIPLOMATA2015\_001\_01N861482|| Cespe | Cebraspe – IRBr Diplomata – Aplicação: 2015 PROVA OBJETIVA – PRIMEIRA FASE – PRIMEIRA ETAPA LÍNGUA PORTUGUESA A distinção entre espetáculo (manifestação legítima da cultura) e simulacro (entretenimento da indústria cultural) tornou-se corrente entre os analistas que se ancoram nos valores modernistas para a compreensão da pós-modernidade. Segundo el | Infere-se do texto que uma das características marcantes da pós-modernidade é a valorização do referente, no contexto das representações do real. 2 Ao comentar a distinção entre espetáculo e simulacro, o autor demonstra, com base em analistas do tema, como a pós-modernidade se manifesta de modo evidente por meio de uma cultura de espetáculo a ser usufruída pela sociedade. 3 O Brasil, segundo o autor do texto, é um dos países que poderá resolver a oposição entre espetáculo e simulacro, uma vez que “já tem a sua história” (R. 60 e 61). 4 O autor do texto comenta que teórico', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Português', 'Interpretação de texto', 'Item 2 (TPS 2015): ||154IRBRDIPLOMATA2015\_001\_01N861482|| Cespe | Cebraspe – IRBr Diplomata – Aplicação: 2015 PROVA OBJETIVA – PRIMEIRA FASE – PRIMEIRA ETAPA LÍNGUA PORTUGUESA A distinção entre espetáculo (manifestação legítima da cultura) e simulacro (entretenimento da indústria cultural) tornou-se corrente entre os analistas que se ancoram nos valores modernistas para a compreensão da pós-modernidade. Segundo el | O narrador informa que o produto Kelene raramente é utilizado em tratamento psiquiátrico.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Português', 'Interpretação de texto', 'Item 3 (TPS 2015): ||154IRBRDIPLOMATA2015\_001\_01N861482|| Cespe | Cebraspe – IRBr Diplomata – Aplicação: 2015 PROVA OBJETIVA – PRIMEIRA FASE – PRIMEIRA ETAPA LÍNGUA PORTUGUESA A distinção entre espetáculo (manifestação legítima da cultura) e simulacro (entretenimento da indústria cultural) tornou-se corrente entre os analistas que se ancoram nos valores modernistas para a compreensão da pós-modernidade. Segundo el | O texto evoca o estranhamento do narrador em relação a jovens que não teriam qualquer razão perceptível para usar Kelene, bem como ao fato de que nenhum dos jovens ofereceu-lhe o anestesiante.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2015, 'Português', 'Interpretação de texto', 'Item 4 (TPS 2015): ||154IRBRDIPLOMATA2015\_001\_01N861482|| Cespe | Cebraspe – IRBr Diplomata – Aplicação: 2015 PROVA OBJETIVA – PRIMEIRA FASE – PRIMEIRA ETAPA LÍNGUA PORTUGUESA A distinção entre espetáculo (manifestação legítima da cultura) e simulacro (entretenimento da indústria cultural) tornou-se corrente entre os analistas que se ancoram nos valores modernistas para a compreensão da pós-modernidade. Segundo el | No texto, não há qualquer evidência de que o narrador, possivelmente mais idoso que as demais pessoas que o acompanham, seja usuário do produto descrito. ||154IRBRDIPLOMATA2015\_001\_01N861482|| Cespe | Cebraspe – IRBr Diplomata – Aplicação: 2015 QUESTÃO 5 1 Celso Cunha tinha, na minha geração literária, a posição que, na geração anterior à nossa, coube a Souza da Silveira. Ou seja: a do mestre que, conhecendo profundamente 4 a língua portuguesa, nas suas minúcias e no seu conjunto, associou a esse saber admirável a sensibilidade de quem nascera para apreciá-la na condiçã', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
