INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2018, 'Português', 'Interpretação de texto', 'Item 1 (TPS 2018): A pena de morte é uma flagrante violação dos direitos humanos e é incompatível com os princípios do tratamento humanitário e do devido processo legal. Ouve-se, por vezes, o argumento de que a pena capital tem efeito dissuasório sobre o crime. No entanto, não há comprovação de que exista relação de causalidade entre a pena de morte e o controle efetivo da criminalidade, nem de que ela seja mais efi | Utilizando, em síntese, os argumentos de que a pena capital viola os direitos humanos, o direito humanitário e o devido processo legal; não tem efeito dissuasório; pode punir pessoas inocentes; tem sido utilizada como ferramenta política; e é ineficaz na luta contra o tráfico de drogas, a diplomata insta os Estados a concluir a negociação do Segundo Protocolo Facultativo do Pacto Internacional dos Direitos Civis e Políticos, destinado a abolir a pena de morte.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Português', 'Interpretação de texto', 'Item 2 (TPS 2018): A pena de morte é uma flagrante violação dos direitos humanos e é incompatível com os princípios do tratamento humanitário e do devido processo legal. Ouve-se, por vezes, o argumento de que a pena capital tem efeito dissuasório sobre o crime. No entanto, não há comprovação de que exista relação de causalidade entre a pena de morte e o controle efetivo da criminalidade, nem de que ela seja mais efi | A diplomata contesta a opinião corrente de que a pena de morte tem efeito dissuasório sobre o crime sob o argumento de que esse tipo de pena é contraproducente, por gerar mais violência, o que, segundo ela, pode ser comprovado pela inexistência de evidências empíricas de relação causal entre a pena de morte e a redução da criminalidade e por sua ineficácia na luta contra o tráfico de drogas.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Português', 'Interpretação de texto', 'Item 3 (TPS 2018): A pena de morte é uma flagrante violação dos direitos humanos e é incompatível com os princípios do tratamento humanitário e do devido processo legal. Ouve-se, por vezes, o argumento de que a pena capital tem efeito dissuasório sobre o crime. No entanto, não há comprovação de que exista relação de causalidade entre a pena de morte e o controle efetivo da criminalidade, nem de que ela seja mais efi | A diplomata emprega a expressão “sanção discriminatória” (R.15) para se referir à seletividade e arbitrariedade de penas de morte aplicadas a indivíduos pobres ou pertencentes a minorias raciais, étnicas ou religiosas, sem estender a interpretação do conceito a práticas de genocídio.', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2018, 'Português', 'Interpretação de texto', 'Item 4 (TPS 2018): A pena de morte é uma flagrante violação dos direitos humanos e é incompatível com os princípios do tratamento humanitário e do devido processo legal. Ouve-se, por vezes, o argumento de que a pena capital tem efeito dissuasório sobre o crime. No entanto, não há comprovação de que exista relação de causalidade entre a pena de morte e o controle efetivo da criminalidade, nem de que ela seja mais efi | Ao defender a tese de que o castigo deve ser proporcional à gravidade do delito, no último período do terceiro parágrafo, a diplomata introduz novo elemento no curso da argumentação, sem conexão com as ideias expressas nos dois períodos anteriores desse mesmo parágrafo, que tratam do tráfico de drogas. Espaço livre CESPE | CEBRASPE – IRBr – Aplicação: 2018 QUESTÃO 2 Texto II 1 O Brasil se absteve na votação do projeto de resolução sobre “a deterioração grave e contínua dos direitos humanos e da situação humanitária na República Árabe da 4 Síria”. Estamos plenamente consci', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
