INSERT INTO questions (source, year, subject, topic, enunciado, opcoes, gabarito, explicacao) VALUES
  ('exam', 2019, 'Português', 'Macroeconomia', 'Item 1 (TPS 2019): EDITAL Nº 1, DE 5 DE JULHO DE 2019 CONCURSO DE ADMISSÃO À CARREIRA DE DIPLOMATA CARGO: TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA Data e horário da prova: domingo, 8/9/2019, às 9h30. • Você receberá do fiscal: o um caderno da prova objetiva contendo 34 (trinta e quatro) questões, e cada questão será composta por 4 (quatro) itens; e o uma folha de respostas personalizada. • Verifique se a numeraç | Nilo Peçanha deferiu o pedido de inscrição de Maria José de Castro Rebello Mendes no certame para a contratação de terceiro oficial da Secretaria de Estado, em razão da carência de pessoal por que vinha passando essa secretaria há mais de uma década. 2 Em seu despacho, o chanceler demonstra apoio irrestrito à inscrição de Maria José de Castro Rebello Mendes, dados os dispositivos legais vigentes à época a esse respeito. 3 As instruções aprovadas por meio do Decreto no 12.998, de 24 de abril de 1918, para os concursos para terceiros oficiais da Secretaria de Estado vêm sen', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Política Internacional', NULL, 'Item 2 (TPS 2019) — consulte o caderno original', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Português', 'MERCOSUL e integração regional', 'Item 3 (TPS 2019): EDITAL Nº 1, DE 5 DE JULHO DE 2019 CONCURSO DE ADMISSÃO À CARREIRA DE DIPLOMATA CARGO: TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA Data e horário da prova: domingo, 8/9/2019, às 9h30. • Você receberá do fiscal: o um caderno da prova objetiva contendo 34 (trinta e quatro) questões, e cada questão será composta por 4 (quatro) itens; e o uma folha de respostas personalizada. • Verifique se a numeraç | As relações da Argentina com o Brasil, durante a presidência de Nestor Kirchner, foram marcadas pela convergência quanto ao pretendido revigoramento do MERCOSUL, pelo decidido apoio ao projeto brasileiro de organizar o espaço político sul-americano por meio da Comunidade Sul-Americana de Nações e pela atuação conjunta na construção de parcerias com os demais países emergentes. 4 A aproximação com os países da Aliança do Pacífico, a ênfase no liberalismo comercial e o interesse em concluir as negociações visando à instauração de uma área de livre comércio entre o MERCOSUL ', '{"a":"Certo","b":"Errado"}'::jsonb, 'b', NULL),
  ('exam', 2019, 'Português', 'Guerra Fria', 'Item 4 (TPS 2019): EDITAL Nº 1, DE 5 DE JULHO DE 2019 CONCURSO DE ADMISSÃO À CARREIRA DE DIPLOMATA CARGO: TERCEIRO-SECRETÁRIO DA CARREIRA DE DIPLOMATA Data e horário da prova: domingo, 8/9/2019, às 9h30. • Você receberá do fiscal: o um caderno da prova objetiva contendo 34 (trinta e quatro) questões, e cada questão será composta por 4 (quatro) itens; e o uma folha de respostas personalizada. • Verifique se a numeraç | O Brasil mantém relações diplomáticas com a Rússia desde o século 19, as quais foram rompidas apenas uma vez: durante a Guerra Fria, entre 1947 e 1961. Nem sempre essas relações convergiram, por exemplo, no âmbito dos BRICS, sendo que o Brasil tem se posicionado de modo contrário às propostas russas de maior regulamentação e controle do fluxo de informações na internet. QUESTÃO 19 O relacionamento com os países da América do Sul representa importante dimensão da política externa brasileira, retratada em iniciativas de natureza política e econômica. A esse respeito, julgue', '{"a":"Certo","b":"Errado"}'::jsonb, 'a', NULL),
